/* Wortabolario — VERBI
   Un verbo per riga. Campi: inf, pres (3ª pers.), pra (Präteritum), perf (Perfekt), it, en,
   ex/enex = esempi [tedesco, traduzione], note/enNote, cat (categoria). */

const VERBI = [
  {inf:"sein", pres:"ist", pra:"war", perf:"ist gewesen", it:"essere", en:"to be", ex:[["Ich bin müde.","Sono stanco."]], enex:[["Ich bin müde.","I am tired."]], note:"Verbo ausiliare irregolare, usa sein al Perfekt.", enNote:"Irregular auxiliary verb, uses sein in the Perfekt.", cat:"ausiliare"},
  {inf:"haben", pres:"hat", pra:"hatte", perf:"hat gehabt", it:"avere", en:"to have", ex:[["Er hat Zeit.","Lui ha tempo."]], enex:[["Er hat Zeit.","He has time."]], note:"Ausiliare per la maggior parte dei verbi al Perfekt.", enNote:"Auxiliary for most verbs in the Perfekt.", cat:"ausiliare"},
  {inf:"werden", pres:"wird", pra:"wurde", perf:"ist geworden", it:"diventare", en:"to become", ex:[["Sie wird Ärztin.","Lei diventa dottoressa."]], enex:[["Sie wird Ärztin.","She is becoming a doctor."]], note:"Usato anche per formare il Futur I e il passivo.", enNote:"Also used to form the Futur I and the passive.", cat:"ausiliare"},
  {inf:"können", pres:"kann", pra:"konnte", perf:"hat gekonnt", it:"potere / sapere fare", en:"can / to be able to", ex:[["Ich kann schwimmen.","Io so nuotare."]], enex:[["Ich kann schwimmen.","I can swim."]], note:"Modale: al Perfekt spesso infinito doppio.", enNote:"Modal verb: often uses a double infinitive in the Perfekt.", cat:"modale"},
  {inf:"müssen", pres:"muss", pra:"musste", perf:"hat gemusst", it:"dovere (necessità)", en:"must / to have to", ex:[["Wir müssen gehen.","Dobbiamo andare."]], enex:[["Wir müssen gehen.","We have to go."]], note:"Obbligo interno o necessità oggettiva.", enNote:"Internal obligation or objective necessity.", cat:"modale"},
  {inf:"wollen", pres:"will", pra:"wollte", perf:"hat gewollt", it:"volere", en:"to want", ex:[["Ich will das nicht.","Non voglio questo."]], enex:[["Ich will das nicht.","I don't want this."]], note:"Volontà propria del parlante.", enNote:"The speaker's own will.", cat:"modale"},
  {inf:"sollen", pres:"soll", pra:"sollte", perf:"hat gesollt", it:"dovere (per ordine altrui)", en:"should / to be supposed to", ex:[["Du sollst pünktlich sein.","Dovresti essere puntuale."]], enex:[["Du sollst pünktlich sein.","You should be punctual."]], note:"Obbligo o consiglio dato da altri.", enNote:"Obligation or advice given by others.", cat:"modale"},
  {inf:"dürfen", pres:"darf", pra:"durfte", perf:"hat gedurft", it:"potere (permesso)", en:"may / to be allowed to", ex:[["Man darf hier nicht rauchen.","Non si può fumare qui."]], enex:[["Man darf hier nicht rauchen.","You're not allowed to smoke here."]], note:"Permesso o divieto se negato.", enNote:"Permission, or prohibition if negated.", cat:"modale"},
  {inf:"mögen", pres:"mag", pra:"mochte", perf:"hat gemocht", it:"piacere / gradire", en:"to like", ex:[["Ich mag Kaffee.","Mi piace il caffè."]], enex:[["Ich mag Kaffee.","I like coffee."]], note:"Al condizionale diventa 'möchte' = vorrei.", enNote:"In the conditional it becomes 'möchte' = I would like.", cat:"modale"},
  {inf:"gehen", pres:"geht", pra:"ging", perf:"ist gegangen", it:"andare (a piedi)", en:"to go", ex:[["Wir gehen ins Kino.","Andiamo al cinema."]], enex:[["Wir gehen ins Kino.","We're going to the cinema."]], note:"Verbo di moto: usa sein al Perfekt.", enNote:"Motion verb: uses sein in the Perfekt.", cat:"movimento"},
  {inf:"kommen", pres:"kommt", pra:"kam", perf:"ist gekommen", it:"venire", en:"to come", ex:[["Er kommt später.","Lui viene più tardi."]], enex:[["Er kommt später.","He's coming later."]], note:"Präteritum: ich kam, wir kamen.", enNote:"Präteritum: ich kam, wir kamen.", cat:"movimento"},
  {inf:"fahren", pres:"fährt", pra:"fuhr", perf:"ist gefahren", it:"andare (con un mezzo)", en:"to drive / go", ex:[["Sie fährt nach Berlin.","Lei va a Berlino."]], enex:[["Sie fährt nach Berlin.","She's going to Berlin."]], note:"Cambia vocale a→ä al presente.", enNote:"Vowel changes a→ä in the present tense.", cat:"movimento"},
  {inf:"fliegen", pres:"fliegt", pra:"flog", perf:"ist geflogen", it:"volare", en:"to fly", ex:[["Wir fliegen nach Rom.","Voliamo a Roma."]], enex:[["Wir fliegen nach Rom.","We're flying to Rome."]], note:"", enNote:"", cat:"movimento"},
  {inf:"laufen", pres:"läuft", pra:"lief", perf:"ist gelaufen", it:"camminare / andare a piedi", en:"to walk / to run (general)", ex:[["Er läuft jeden Morgen zur Arbeit.","Lui va a piedi al lavoro ogni mattina."]], enex:[["Er läuft jeden Morgen zur Arbeit.","He walks to work every morning."]], note:"Cambia au→äu al presente. Nell'uso quotidiano indica 'camminare/andare a piedi'; per 'correre veloce' si usa rennen.", enNote:"Vowel changes au→äu in the present tense. In everyday use it means 'to walk'; for 'to run fast' rennen is used.", cat:"movimento"},
  {inf:"rennen", pres:"rennt", pra:"rannte", perf:"ist gerannt", it:"correre (velocemente)", en:"to run (fast)", ex:[["Das Kind rennt zur Schule.","Il bambino corre a scuola di corsa."]], enex:[["Das Kind rennt zur Schule.","The child runs to school."]], note:"Verbo misto. Indica una corsa veloce, a differenza di laufen (camminare/andare).", enNote:"Mixed verb. Indicates fast running, unlike laufen (to walk/go).", cat:"movimento"},
  {inf:"bleiben", pres:"bleibt", pra:"blieb", perf:"ist geblieben", it:"rimanere", en:"to stay", ex:[["Ich bleibe zu Hause.","Rimango a casa."]], enex:[["Ich bleibe zu Hause.","I'm staying home."]], note:"Richiede sein anche se non è moto fisico.", enNote:"Takes sein even though it's not physical motion.", cat:"movimento"},
  {inf:"steigen", pres:"steigt", pra:"stieg", perf:"ist gestiegen", it:"salire", en:"to climb / rise", ex:[["Die Preise steigen.","I prezzi salgono."]], enex:[["Die Preise steigen.","Prices are rising."]], note:"Anche in senso figurato.", enNote:"Also used figuratively.", cat:"movimento"},
  {inf:"fallen", pres:"fällt", pra:"fiel", perf:"ist gefallen", it:"cadere", en:"to fall", ex:[["Das Buch fällt vom Tisch.","Il libro cade dal tavolo."]], enex:[["Das Buch fällt vom Tisch.","The book falls off the table."]], note:"", enNote:"", cat:"movimento"},
  {inf:"springen", pres:"springt", pra:"sprang", perf:"ist gesprungen", it:"saltare", en:"to jump", ex:[["Das Kind springt hoch.","Il bambino salta in alto."]], enex:[["Das Kind springt hoch.","The child jumps high."]], note:"", enNote:"", cat:"movimento"},
  {inf:"ziehen", pres:"zieht", pra:"zog", perf:"hat/ist gezogen", it:"tirare / traslocare", en:"to pull / move", ex:[["Wir ziehen nach München.","Traslochiamo a Monaco."]], enex:[["Wir ziehen nach München.","We're moving to Munich."]], note:"hat gezogen = tirare; ist gezogen = traslocare.", enNote:"hat gezogen = to pull; ist gezogen = to move (house).", cat:"movimento"},
  {inf:"sehen", pres:"sieht", pra:"sah", perf:"hat gesehen", it:"vedere", en:"to see", ex:[["Ich sehe dich.","Ti vedo."]], enex:[["Ich sehe dich.","I see you."]], note:"Cambia e→ie al presente. Con un secondo verbo il Perfekt ha due infiniti: Ich habe ihn kommen sehen (mai «gesehen»).", enNote:"Vowel changes e→ie in the present tense. With a second verb the Perfekt has two infinitives: Ich habe ihn kommen sehen (never «gesehen»).", cat:"percezione"},
  {inf:"lesen", pres:"liest", pra:"las", perf:"hat gelesen", it:"leggere", en:"to read", ex:[["Sie liest ein Buch.","Lei legge un libro."]], enex:[["Sie liest ein Buch.","She's reading a book."]], note:"Cambia e→ie al presente.", enNote:"Vowel changes e→ie in the present tense.", cat:"percezione"},
  {inf:"sprechen", pres:"spricht", pra:"sprach", perf:"hat gesprochen", it:"parlare", en:"to speak", ex:[["Er spricht Deutsch.","Lui parla tedesco."]], enex:[["Er spricht Deutsch.","He speaks German."]], note:"Cambia e→i al presente.", enNote:"Vowel changes e→i in the present tense.", cat:"comunicazione"},
  {inf:"schreiben", pres:"schreibt", pra:"schrieb", perf:"hat geschrieben", it:"scrivere", en:"to write", ex:[["Ich schreibe einen Brief.","Scrivo una lettera."]], enex:[["Ich schreibe einen Brief.","I'm writing a letter."]], note:"", enNote:"", cat:"comunicazione"},
  {inf:"verstehen", pres:"versteht", pra:"verstand", perf:"hat verstanden", it:"capire", en:"to understand", ex:[["Verstehst du mich?","Mi capisci?"]], enex:[["Verstehst du mich?","Do you understand me?"]], note:"Composto di stehen.", enNote:"Compound of stehen.", cat:"comunicazione"},
  {inf:"heißen", pres:"heißt", pra:"hieß", perf:"hat geheißen", it:"chiamarsi", en:"to be called", ex:[["Ich heiße Marco.","Mi chiamo Marco."]], enex:[["Ich heiße Marco.","My name is Marco."]], note:"", enNote:"", cat:"comunicazione"},
  {inf:"rufen", pres:"ruft", pra:"rief", perf:"hat gerufen", it:"chiamare / gridare", en:"to call", ex:[["Sie ruft ihn an.","Lei lo chiama."]], enex:[["Sie ruft ihn an.","She's calling him."]], note:"Base del separabile 'anrufen' = telefonare. Perfekt con un altro verbo: Ich habe dich rufen hören / Er hat mich rufen lassen.", enNote:"Base of the separable verb 'anrufen' = to phone. Perfekt with another verb: Ich habe dich rufen hören / Er hat mich rufen lassen.", cat:"comunicazione"},
  {inf:"essen", pres:"isst", pra:"aß", perf:"hat gegessen", it:"mangiare", en:"to eat", ex:[["Wir essen zusammen.","Mangiamo insieme."]], enex:[["Wir essen zusammen.","We're eating together."]], note:"Cambia e→i al presente.", enNote:"Vowel changes e→i in the present tense.", cat:"quotidiano"},
  {inf:"trinken", pres:"trinkt", pra:"trank", perf:"hat getrunken", it:"bere", en:"to drink", ex:[["Er trinkt Wasser.","Lui beve acqua."]], enex:[["Er trinkt Wasser.","He drinks water."]], note:"", enNote:"", cat:"quotidiano"},
  {inf:"geben", pres:"gibt", pra:"gab", perf:"hat gegeben", it:"dare", en:"to give", ex:[["Ich gebe dir das Buch.","Ti do il libro."]], enex:[["Ich gebe dir das Buch.","I'm giving you the book."]], note:"Regge il dativo. Präteritum: gab, gaben.", enNote:"Takes the dative. Präteritum: gab, gaben.", cat:"quotidiano"},
  {inf:"nehmen", pres:"nimmt", pra:"nahm", perf:"hat genommen", it:"prendere", en:"to take", ex:[["Sie nimmt den Bus.","Lei prende l'autobus."]], enex:[["Sie nimmt den Bus.","She's taking the bus."]], note:"nehmen→nimmt.", enNote:"nehmen→nimmt.", cat:"quotidiano"},
  {inf:"helfen", pres:"hilft", pra:"half", perf:"hat geholfen", it:"aiutare", en:"to help", ex:[["Kannst du mir helfen?","Puoi aiutarmi?"]], enex:[["Kannst du mir helfen?","Can you help me?"]], note:"Regge il dativo.", enNote:"Takes the dative.", cat:"quotidiano"},
  {inf:"treffen", pres:"trifft", pra:"traf", perf:"hat getroffen", it:"incontrare", en:"to meet", ex:[["Ich treffe meine Freunde.","Incontro i miei amici."]], enex:[["Ich treffe meine Freunde.","I'm meeting my friends."]], note:"", enNote:"", cat:"quotidiano"},
  {inf:"tragen", pres:"trägt", pra:"trug", perf:"hat getragen", it:"portare / indossare", en:"to carry / wear", ex:[["Sie trägt eine Jacke.","Lei indossa una giacca."]], enex:[["Sie trägt eine Jacke.","She's wearing a jacket."]], note:"", enNote:"", cat:"quotidiano"},
  {inf:"schlafen", pres:"schläft", pra:"schlief", perf:"hat geschlafen", it:"dormire", en:"to sleep", ex:[["Das Baby schläft.","Il bambino dorme."]], enex:[["Das Baby schläft.","The baby is sleeping."]], note:"", enNote:"", cat:"quotidiano"},
  {inf:"waschen", pres:"wäscht", pra:"wusch", perf:"hat gewaschen", it:"lavare", en:"to wash", ex:[["Ich wasche das Auto.","Lavo la macchina."]], enex:[["Ich wasche das Auto.","I'm washing the car."]], note:"Vedi anche 'sich waschen' (riflessivo).", enNote:"See also 'sich waschen' (reflexive).", cat:"quotidiano"},
  {inf:"finden", pres:"findet", pra:"fand", perf:"hat gefunden", it:"trovare", en:"to find", ex:[["Ich finde den Weg nicht.","Non trovo la strada."]], enex:[["Ich finde den Weg nicht.","I can't find the way."]], note:"Präteritum: fand, fanden.", enNote:"Präteritum: fand, fanden.", cat:"mentale"},
  {inf:"wissen", pres:"weiß", pra:"wusste", perf:"hat gewusst", it:"sapere", en:"to know (fact)", ex:[["Ich weiß es nicht.","Non lo so."]], enex:[["Ich weiß es nicht.","I don't know."]], note:"Irregolare anche al presente: ich weiß.", enNote:"Irregular in the present too: ich weiß.", cat:"mentale"},
  {inf:"kennen", pres:"kennt", pra:"kannte", perf:"hat gekannt", it:"conoscere", en:"to know (persona/luogo)", ex:[["Ich kenne ihn gut.","Lo conosco bene."]], enex:[["Ich kenne ihn gut.","I know him well."]], note:"Verbo misto: kannte.", enNote:"Mixed verb: kannte.", cat:"mentale"},
  {inf:"denken", pres:"denkt", pra:"dachte", perf:"hat gedacht", it:"pensare", en:"to think", ex:[["Ich denke an dich.","Penso a te."]], enex:[["Ich denke an dich.","I'm thinking of you."]], note:"Verbo misto: vocale + -te.", enNote:"Mixed verb: vowel + -te.", cat:"mentale"},
  {inf:"vergessen", pres:"vergisst", pra:"vergaß", perf:"hat vergessen", it:"dimenticare", en:"to forget", ex:[["Ich vergesse nie deinen Namen.","Non dimentico mai il tuo nome."]], enex:[["Ich vergesse nie deinen Namen.","I'll never forget your name."]], note:"Cambia e→i.", enNote:"Vowel changes e→i.", cat:"mentale"},
  {inf:"verlieren", pres:"verliert", pra:"verlor", perf:"hat verloren", it:"perdere", en:"to lose", ex:[["Er verliert oft seine Schlüssel.","Lui perde spesso le chiavi."]], enex:[["Er verliert oft seine Schlüssel.","He often loses his keys."]], note:"", enNote:"", cat:"quotidiano"},
  {inf:"beginnen", pres:"beginnt", pra:"begann", perf:"hat begonnen", it:"iniziare", en:"to begin", ex:[["Der Film beginnt um 20 Uhr.","Il film inizia alle 20."]], enex:[["Der Film beginnt um 20 Uhr.","The movie starts at 8pm."]], note:"", enNote:"", cat:"quotidiano"},
  {inf:"anfangen", pres:"fängt an", pra:"fing an", perf:"hat angefangen", it:"iniziare", en:"to start", ex:[["Wann fängt der Kurs an?","Quando inizia il corso?"]], enex:[["Wann fängt der Kurs an?","When does the course start?"]], note:"Separabile: fangen + an.", enNote:"Separable: fangen + an.", cat:"quotidiano"},
  {inf:"anrufen", pres:"ruft an", pra:"rief an", perf:"hat angerufen", it:"telefonare", en:"to call (phone)", ex:[["Ich rufe dich später an.","Ti chiamo più tardi."]], enex:[["Ich rufe dich später an.","I'll call you later."]], note:"Composto separabile di rufen.", enNote:"Separable compound of rufen.", cat:"comunicazione"},
  {inf:"aufstehen", pres:"steht auf", pra:"stand auf", perf:"ist aufgestanden", it:"alzarsi", en:"to get up", ex:[["Ich stehe um 7 Uhr auf.","Mi alzo alle 7."]], enex:[["Ich stehe um 7 Uhr auf.","I get up at 7 o'clock."]], note:"Composto con sein.", enNote:"Takes sein.", cat:"quotidiano"},
  {inf:"einladen", pres:"lädt ein", pra:"lud ein", perf:"hat eingeladen", it:"invitare", en:"to invite", ex:[["Wir laden euch zum Essen ein.","Vi invitiamo a cena."]], enex:[["Wir laden euch zum Essen ein.","We're inviting you to dinner."]], note:"Composto separabile di laden.", enNote:"Separable compound of laden.", cat:"quotidiano"},
  {inf:"stehen", pres:"steht", pra:"stand", perf:"hat gestanden", it:"stare in piedi / essere scritto", en:"to stand", ex:[["Das Auto steht vor dem Haus.","L'auto è ferma davanti alla casa."]], enex:[["Das Auto steht vor dem Haus.","The car is parked in front of the house."]], note:"", enNote:"", cat:"posizione"},
  {inf:"sitzen", pres:"sitzt", pra:"saß", perf:"hat gesessen", it:"sedere / essere seduto", en:"to sit", ex:[["Er sitzt am Tisch.","Lui è seduto al tavolo."]], enex:[["Er sitzt am Tisch.","He's sitting at the table."]], note:"", enNote:"", cat:"posizione"},
  {inf:"liegen", pres:"liegt", pra:"lag", perf:"hat gelegen", it:"giacere / essere sdraiato", en:"to lie", ex:[["Das Handy liegt auf dem Bett.","Il cellulare è sul letto."]], enex:[["Das Handy liegt auf dem Bett.","The phone is on the bed."]], note:"", enNote:"", cat:"posizione"},
  {inf:"singen", pres:"singt", pra:"sang", perf:"hat gesungen", it:"cantare", en:"to sing", ex:[["Sie singt sehr gut.","Lei canta molto bene."]], enex:[["Sie singt sehr gut.","She sings very well."]], note:"", enNote:"", cat:"quotidiano"},
  {inf:"sich waschen", pres:"wäscht sich", pra:"wusch sich", perf:"hat sich gewaschen", it:"lavarsi", en:"to wash oneself", ex:[["Ich wasche mich jeden Morgen.","Mi lavo ogni mattina."]], enex:[["Ich wasche mich jeden Morgen.","I wash myself every morning."]], note:"Accusativo: nessun altro oggetto nella frase.", enNote:"Accusative: no other object in the sentence.", cat:"riflessivo"},
  {inf:"sich anziehen", pres:"zieht sich an", pra:"zog sich an", perf:"hat sich angezogen", it:"vestirsi", en:"to get dressed", ex:[["Sie zieht sich schnell an.","Lei si veste velocemente."]], enex:[["Sie zieht sich schnell an.","She gets dressed quickly."]], note:"Accusativo.", enNote:"Accusative.", cat:"riflessivo"},
  {inf:"sich hinlegen", pres:"legt sich hin", pra:"legte sich hin", perf:"hat sich hingelegt", it:"sdraiarsi", en:"to lie down", ex:[["Er legt sich hin.","Lui si sdraia."]], enex:[["Er legt sich hin.","He lies down."]], note:"Accusativo; verbo debole.", enNote:"Accusative; weak verb.", cat:"riflessivo"},
  {inf:"sich interessieren", pres:"interessiert sich", pra:"interessierte sich", perf:"hat sich interessiert", it:"interessarsi", en:"to be interested", ex:[["Ich interessiere mich für Musik.","Mi interessa la musica."]], enex:[["Ich interessiere mich für Musik.","I'm interested in music."]], note:"Accusativo + für.", enNote:"Accusative + für.", cat:"riflessivo"},
  {inf:"sich aufregen", pres:"regt sich auf", pra:"regte sich auf", perf:"hat sich aufgeregt", it:"arrabbiarsi", en:"to get upset", ex:[["Sie regt sich schnell auf.","Lei si arrabbia velocemente."]], enex:[["Sie regt sich schnell auf.","She gets upset quickly."]], note:"Accusativo.", enNote:"Accusative.", cat:"riflessivo"},
  {inf:"sich die Hände waschen", pres:"wäscht sich die Hände", pra:"wusch sich die Hände", perf:"hat sich die Hände gewaschen", it:"lavarsi le mani", en:"to wash one's hands", ex:[["Ich wasche mir die Hände.","Mi lavo le mani."]], enex:[["Ich wasche mir die Hände.","I wash my hands."]], note:"Dativo (mir) + accusativo (die Hände).", enNote:"Dative (mir) + accusative (die Hände).", cat:"riflessivo"},
  {inf:"sich die Zähne putzen", pres:"putzt sich die Zähne", pra:"putzte sich die Zähne", perf:"hat sich die Zähne geputzt", it:"lavarsi i denti", en:"to brush one's teeth", ex:[["Er putzt sich die Zähne.","Lui si lava i denti."]], enex:[["Er putzt sich die Zähne.","He brushes his teeth."]], note:"Dativo + accusativo.", enNote:"Dative + accusative.", cat:"riflessivo"},
  {inf:"sich etwas kaufen", pres:"kauft sich etwas", pra:"kaufte sich etwas", perf:"hat sich etwas gekauft", it:"comprarsi qualcosa", en:"to buy oneself something", ex:[["Sie kauft sich ein Buch.","Lei si compra un libro."]], enex:[["Sie kauft sich ein Buch.","She buys herself a book."]], note:"Dativo (beneficiario) + accusativo.", enNote:"Dative (beneficiary) + accusative.", cat:"riflessivo"},
  {inf:"machen", pres:"macht", pra:"machte", perf:"hat gemacht", it:"fare", en:"to do / make", ex:[["Was machst du gerade?","Cosa stai facendo?"]], enex:[["Was machst du gerade?","What are you doing right now?"]], note:"Verbo debole (regolare), tra i più usati in assoluto.", enNote:"Weak (regular) verb, among the most commonly used.", cat:"quotidiano"},
  {inf:"sagen", pres:"sagt", pra:"sagte", perf:"hat gesagt", it:"dire", en:"to say", ex:[["Was hat er gesagt?","Cosa ha detto?"]], enex:[["Was hat er gesagt?","What did he say?"]], note:"", enNote:"", cat:"comunicazione"},
  {inf:"fragen", pres:"fragt", pra:"fragte", perf:"hat gefragt", it:"chiedere", en:"to ask", ex:[["Ich frage dich etwas.","Ti chiedo una cosa."]], enex:[["Ich frage dich etwas.","I'm asking you something."]], note:"", enNote:"", cat:"comunicazione"},
  {inf:"antworten", pres:"antwortet", pra:"antwortete", perf:"hat geantwortet", it:"rispondere", en:"to answer", ex:[["Er antwortet nicht.","Lui non risponde."]], enex:[["Er antwortet nicht.","He's not answering."]], note:"Regge il dativo: 'jemandem antworten'.", enNote:"Takes the dative: 'jemandem antworten'.", cat:"comunicazione"},
  {inf:"zeigen", pres:"zeigt", pra:"zeigte", perf:"hat gezeigt", it:"mostrare", en:"to show", ex:[["Zeig mir das Foto.","Mostrami la foto."]], enex:[["Zeig mir das Foto.","Show me the photo."]], note:"jdm etw zeigen: la persona in dativo, la cosa in accusativo. Con il pronome accusativo l'ordine si inverte: Ich zeige ihn euch auf dem Stadtplan.", enNote:"jdm etw zeigen: the person in the dative, the thing in the accusative. With an accusative pronoun the order swaps: Ich zeige ihn euch auf dem Stadtplan.", cat:"comunicazione"},
  {inf:"erzählen", pres:"erzählt", pra:"erzählte", perf:"hat erzählt", it:"raccontare", en:"to tell / narrate", ex:[["Erzähl mir eine Geschichte.","Raccontami una storia."]], enex:[["Erzähl mir eine Geschichte.","Tell me a story."]], note:"Prefisso er-, nessun ge- al Perfekt.", enNote:"Prefix er-, no ge- in the Perfekt.", cat:"comunicazione"},
  {inf:"wohnen", pres:"wohnt", pra:"wohnte", perf:"hat gewohnt", it:"abitare", en:"to live / reside", ex:[["Ich wohne in Berlin.","Abito a Berlino."]], enex:[["Ich wohne in Berlin.","I live in Berlin."]], note:"Per l'indirizzo/residenza; per 'vivere' in senso ampio si usa leben.", enNote:"For address/residence; for 'to live' in a broader sense, leben is used.", cat:"quotidiano"},
  {inf:"leben", pres:"lebt", pra:"lebte", perf:"hat gelebt", it:"vivere", en:"to live", ex:[["Meine Großeltern leben noch.","I miei nonni vivono ancora."]], enex:[["Meine Großeltern leben noch.","My grandparents are still alive."]], note:"", enNote:"", cat:"quotidiano"},
  {inf:"arbeiten", pres:"arbeitet", pra:"arbeitete", perf:"hat gearbeitet", it:"lavorare", en:"to work", ex:[["Sie arbeitet viel.","Lei lavora molto."]], enex:[["Sie arbeitet viel.","She works a lot."]], note:"-et alla 3ª persona e al Präteritum (radice finisce in -t).", enNote:"-et in the 3rd person and in the Präteritum (stem ends in -t).", cat:"lavoro"},
  {inf:"spielen", pres:"spielt", pra:"spielte", perf:"hat gespielt", it:"giocare / suonare", en:"to play", ex:[["Die Kinder spielen im Park.","I bambini giocano al parco."]], enex:[["Die Kinder spielen im Park.","The children play in the park."]], note:"", enNote:"", cat:"quotidiano"},
  {inf:"kaufen", pres:"kauft", pra:"kaufte", perf:"hat gekauft", it:"comprare", en:"to buy", ex:[["Ich kaufe Brot.","Compro il pane."]], enex:[["Ich kaufe Brot.","I'm buying bread."]], note:"Anche con due oggetti: jdm etw kaufen = comprare qualcosa a qualcuno. Die Nachbarin kauft ihrer Tochter ein Buch.", enNote:"Also with two objects: jdm etw kaufen = to buy someone something. Die Nachbarin kauft ihrer Tochter ein Buch.", cat:"quotidiano"},
  {inf:"verkaufen", pres:"verkauft", pra:"verkaufte", perf:"hat verkauft", it:"vendere", en:"to sell", ex:[["Er verkauft sein Auto.","Lui vende la sua auto."]], enex:[["Er verkauft sein Auto.","He's selling his car."]], note:"Prefisso ver-, nessun ge- al Perfekt.", enNote:"Prefix ver-, no ge- in the Perfekt.", cat:"quotidiano"},
  {inf:"bezahlen", pres:"bezahlt", pra:"bezahlte", perf:"hat bezahlt", it:"pagare", en:"to pay", ex:[["Ich bezahle mit Karte.","Pago con la carta."]], enex:[["Ich bezahle mit Karte.","I'm paying by card."]], note:"Prefisso be-, nessun ge- al Perfekt.", enNote:"Prefix be-, no ge- in the Perfekt.", cat:"quotidiano"},
  {inf:"kosten", pres:"kostet", pra:"kostete", perf:"hat gekostet", it:"costare", en:"to cost", ex:[["Was kostet das?","Quanto costa?"]], enex:[["Was kostet das?","How much does that cost?"]], note:"", enNote:"", cat:"quotidiano"},
  {inf:"brauchen", pres:"braucht", pra:"brauchte", perf:"hat gebraucht", it:"aver bisogno di", en:"to need", ex:[["Ich brauche Hilfe.","Ho bisogno di aiuto."]], enex:[["Ich brauche Hilfe.","I need help."]], note:"", enNote:"", cat:"quotidiano"},
  {inf:"lernen", pres:"lernt", pra:"lernte", perf:"hat gelernt", it:"imparare / studiare", en:"to learn / study", ex:[["Ich lerne Deutsch.","Sto imparando il tedesco."]], enex:[["Ich lerne Deutsch.","I'm learning German."]], note:"", enNote:"", cat:"quotidiano"},
  {inf:"kochen", pres:"kocht", pra:"kochte", perf:"hat gekocht", it:"cucinare", en:"to cook", ex:[["Wer kocht heute?","Chi cucina oggi?"]], enex:[["Wer kocht heute?","Who's cooking today?"]], note:"", enNote:"", cat:"quotidiano"},
  {inf:"putzen", pres:"putzt", pra:"putzte", perf:"hat geputzt", it:"pulire", en:"to clean", ex:[["Ich putze die Wohnung.","Pulisco l'appartamento."]], enex:[["Ich putze die Wohnung.","I'm cleaning the apartment."]], note:"", enNote:"", cat:"quotidiano"},
  {inf:"öffnen", pres:"öffnet", pra:"öffnete", perf:"hat geöffnet", it:"aprire", en:"to open", ex:[["Kannst du das Fenster öffnen?","Puoi aprire la finestra?"]], enex:[["Kannst du das Fenster öffnen?","Can you open the window?"]], note:"-et alla 3ª persona e al Präteritum.", enNote:"-et in the 3rd person and in the Präteritum.", cat:"quotidiano"},
  {inf:"tun", pres:"tut", pra:"tat", perf:"hat getan", it:"fare / agire", en:"to do", ex:[["Was soll ich tun?","Cosa dovrei fare?"]], enex:[["Was soll ich tun?","What should I do?"]], note:"Irregolare; simile a machen ma più usato in espressioni fisse.", enNote:"Irregular; similar to machen but more used in set expressions.", cat:"quotidiano"},
  {inf:"gefallen", pres:"gefällt", pra:"gefiel", perf:"hat gefallen", it:"piacere", en:"to please / like", ex:[["Das Kleid gefällt mir.","Mi piace il vestito."]], enex:[["Das Kleid gefällt mir.","I like the dress."]], note:"Regge il dativo: 'mir gefällt...' = 'mi piace...'.", enNote:"Takes the dative: 'mir gefällt...' = 'I like...'.", cat:"mentale"},
  {inf:"bringen", pres:"bringt", pra:"brachte", perf:"hat gebracht", it:"portare", en:"to bring", ex:[["Bring mir bitte das Buch.","Portami il libro, per favore."]], enex:[["Bring mir bitte das Buch.","Please bring me the book."]], note:"Verbo misto (come denken, kennen).", enNote:"Mixed verb (like denken, kennen).", cat:"quotidiano"},
  {inf:"versuchen", pres:"versucht", pra:"versuchte", perf:"hat versucht", it:"provare / tentare", en:"to try", ex:[["Ich versuche es noch einmal.","Ci provo di nuovo."]], enex:[["Ich versuche es noch einmal.","I'm trying it again."]], note:"Prefisso ver-, nessun ge- al Perfekt.", enNote:"Prefix ver-, no ge- in the Perfekt.", cat:"mentale"},
  {inf:"passieren", pres:"passiert", pra:"passierte", perf:"ist passiert", it:"succedere / accadere", en:"to happen", ex:[["Was ist passiert?","Cosa è successo?"]], enex:[["Was ist passiert?","What happened?"]], note:"Verbi in -ieren non prendono ge- al Partizip II.", enNote:"Verbs ending in -ieren don't take ge- in the Partizip II.", cat:"quotidiano"},
  {inf:"backen", pres:"bäckt / backt", pra:"backte", perf:"hat gebacken", it:"infornare / cuocere al forno", en:"to bake", ex:[["Ich backe einen Kuchen.","Inforno una torta."]], enex:[["Ich backe einen Kuchen.","I'm baking a cake."]], note:"Regge l'accusativo (etwas backen). Il Partizip II è forte (gebacken) anche se il Präteritum è debole (backte) — forma mista.", enNote:"Takes the accusative (etwas backen). The Partizip II is strong (gebacken) even though the Präteritum is weak (backte) — a mixed pattern.", cat:"quotidiano"},
  {inf:"telefonieren", pres:"telefoniert", pra:"telefonierte", perf:"hat telefoniert", it:"telefonare", en:"to phone", ex:[["Ich habe mit Anna telefoniert.","Ho telefonato con Anna."]], enex:[["Ich habe mit Anna telefoniert.","I spoke with Anna on the phone."]], note:"Sempre con la preposizione mit + dativo. Diverso da anrufen, che regge l'accusativo: Ich habe Anna angerufen.", enNote:"Always with the preposition mit + dative. Unlike anrufen, which takes the accusative: Ich habe Anna angerufen.", cat:"comunicazione"},
  {inf:"betreuen", pres:"betreut", pra:"betreute", perf:"hat betreut", it:"assistere / prendersi cura", en:"to look after / to supervise", ex:[["Sie betreut ihre alte Mutter.","Lei si prende cura della madre anziana."]], enex:[["Sie betreut ihre alte Mutter.","She looks after her elderly mother."]], note:"jdn/etw betreuen — regge l'accusativo.", enNote:"jdn/etw betreuen — takes the accusative.", cat:"quotidiano"},
  {inf:"schmeißen", pres:"schmeißt", pra:"schmiss", perf:"hat geschmissen", it:"buttare / gettare", en:"to chuck / to throw", ex:[["Schmeiß das nicht auf den Boden!","Non buttarlo per terra!"]], enex:[["Schmeiß das nicht auf den Boden!","Don't throw that on the floor!"]], note:"Colloquiale; equivalente più neutro: werfen.", enNote:"Colloquial; the more neutral equivalent is werfen.", cat:"quotidiano"},
  {inf:"erledigen", pres:"erledigt", pra:"erledigte", perf:"hat erledigt", it:"sbrigare / arrangiare", en:"to take care of / to get done", ex:[["Ich muss noch zwei Sachen erledigen.","Devo ancora sbrigare due cose."]], enex:[["Ich muss noch zwei Sachen erledigen.","I still have two things to take care of."]], note:"etw Akk erledigen.", enNote:"etw Akk erledigen.", cat:"lavoro"},
  {inf:"versprechen", pres:"verspricht", pra:"versprach", perf:"hat versprochen", it:"promettere", en:"to promise", ex:[["Er hat mir Hilfe versprochen.","Mi ha promesso aiuto."]], enex:[["Er hat mir Hilfe versprochen.","He promised me help."]], note:"jdm etw Akk versprechen. Cambia e→i al presente. Sostantivo: das Versprechen.", enNote:"jdm etw Akk versprechen. Vowel changes e→i in the present. Noun: das Versprechen.", cat:"comunicazione"},
  {inf:"empfangen", pres:"empfängt", pra:"empfing", perf:"hat empfangen", it:"ricevere / accogliere", en:"to receive / to welcome", ex:[["Wir empfangen heute Gäste.","Oggi riceviamo ospiti."]], enex:[["Wir empfangen heute Gäste.","We're receiving guests today."]], note:"etw/jdn empfangen. Cambia a→ä al presente. Sostantivo: der Empfang.", enNote:"etw/jdn empfangen. Vowel changes a→ä in the present. Noun: der Empfang.", cat:"quotidiano"},
  {inf:"verlangen", pres:"verlangt", pra:"verlangte", perf:"hat verlangt", it:"pretendere / esigere", en:"to demand / to require", ex:[["Er verlangt zu viel von mir.","Pretende troppo da me."]], enex:[["Er verlangt zu viel von mir.","He demands too much from me."]], note:"etw Akk verlangen; von jdm etwas verlangen.", enNote:"etw Akk verlangen; von jdm etwas verlangen.", cat:"comunicazione"},
  {inf:"wiegen", pres:"wiegt", pra:"wog", perf:"hat gewogen", it:"pesare", en:"to weigh", ex:[["Das Paket wiegt drei Kilo.","Il pacco pesa tre chili."]], enex:[["Das Paket wiegt drei Kilo.","The parcel weighs three kilos."]], note:"Sia intransitivo (avere un peso) sia transitivo: jdn/etw wiegen, sich Akk wiegen = pesarsi.", enNote:"Both intransitive (to have a weight) and transitive: jdn/etw wiegen, sich Akk wiegen = to weigh oneself.", cat:"quotidiano"},
  {inf:"verschwinden", pres:"verschwindet", pra:"verschwand", perf:"ist verschwunden", it:"sparire / svanire", en:"to disappear / to vanish", ex:[["Der Schlüssel ist verschwunden.","La chiave è sparita."]], enex:[["Der Schlüssel ist verschwunden.","The key has disappeared."]], note:"Usa sein al Perfekt. Il participio verschwunden si usa anche come aggettivo.", enNote:"Takes sein in the Perfekt. The participle verschwunden is also used as an adjective.", cat:"movimento"},
  {inf:"ausrechnen", pres:"rechnet aus", pra:"rechnete aus", perf:"hat ausgerechnet", it:"calcolare", en:"to calculate / to work out", ex:[["Ich rechne mir die Kosten aus.","Mi calcolo i costi."]], enex:[["Ich rechne mir die Kosten aus.","I'm working out the costs for myself."]], note:"Separabile. etw Akk ausrechnen; con sich Dat = farsi i conti, aspettarsi qualcosa.", enNote:"Separable. etw Akk ausrechnen; with sich Dat = to reckon on, to expect something.", cat:"mentale"},
  {inf:"sich schminken", pres:"schminkt sich", pra:"schminkte sich", perf:"hat sich geschminkt", it:"truccarsi", en:"to put on make-up", ex:[["Ich schminke mich jeden Morgen.","Mi trucco ogni mattina."]], enex:[["Ich schminke mich jeden Morgen.","I put on make-up every morning."]], note:"Riflessivo all'accusativo. Se si nomina la parte del corpo diventa dativo: Ich schminke mir die Augen.", enNote:"Reflexive in the accusative. If the body part is named it becomes dative: Ich schminke mir die Augen.", cat:"riflessivo"},
  {inf:"sich beschweren", pres:"beschwert sich", pra:"beschwerte sich", perf:"hat sich beschwert", it:"lamentarsi", en:"to complain", ex:[["Er beschwert sich über das Essen.","Si lamenta del cibo."]], enex:[["Er beschwert sich über das Essen.","He's complaining about the food."]], note:"sich Akk über etw Akk beschweren. Sostantivo: die Beschwerde.", enNote:"sich Akk über etw Akk beschweren. Noun: die Beschwerde.", cat:"riflessivo"},
  {inf:"sich unterhalten", pres:"unterhält sich", pra:"unterhielt sich", perf:"hat sich unterhalten", it:"conversare / intrattenersi", en:"to chat / to converse", ex:[["Wir haben uns lange unterhalten.","Abbiamo conversato a lungo."]], enex:[["Wir haben uns lange unterhalten.","We chatted for a long time."]], note:"sich Akk mit jdm über etw Akk unterhalten. Inseparabile: il participio non ha ge-.", enNote:"sich Akk mit jdm über etw Akk unterhalten. Inseparable: the participle has no ge-.", cat:"comunicazione"},
  {inf:"schrumpfen", pres:"schrumpft", pra:"schrumpfte", perf:"ist geschrumpft", it:"restringersi / contrarsi", en:"to shrink", ex:[["Der Pullover ist geschrumpft.","Il maglione si è ristretto."]], enex:[["Der Pullover ist geschrumpft.","The sweater has shrunk."]], note:"Usa sein al Perfekt perché indica un cambiamento di stato.", enNote:"Takes sein in the Perfekt because it expresses a change of state.", cat:"quotidiano"},
  {inf:"vermuten", pres:"vermutet", pra:"vermutete", perf:"hat vermutet", it:"supporre / presumere", en:"to suppose / to presume", ex:[["Ich vermute, dass er krank ist.","Suppongo che sia malato."]], enex:[["Ich vermute, dass er krank ist.","I suppose he's ill."]], note:"etw Akk vermuten. Sostantivo: die Vermutung.", enNote:"etw Akk vermuten. Noun: die Vermutung.", cat:"mentale"},
  {inf:"jobben", pres:"jobbt", pra:"jobbte", perf:"hat gejobbt", it:"fare qualche lavoretto", en:"to work odd jobs", ex:[["Im Sommer jobbe ich in einem Café.","D'estate faccio dei lavoretti in un bar."]], enex:[["Im Sommer jobbe ich in einem Café.","In summer I work odd jobs in a café."]], note:"Colloquiale, tipico di studenti; lavoro occasionale, non la professione.", enNote:"Colloquial, typical of students; casual work, not one's profession.", cat:"lavoro"},
  {inf:"stürzen", pres:"stürzt", pra:"stürzte", perf:"ist gestürzt", it:"cadere rovinosamente", en:"to fall / to crash down", ex:[["Sie ist auf dem Eis gestürzt.","È caduta rovinosamente sul ghiaccio."]], enex:[["Sie ist auf dem Eis gestürzt.","She fell hard on the ice."]], note:"Più violento di fallen. Usa sein al Perfekt.", enNote:"More violent than fallen. Takes sein in the Perfekt.", cat:"movimento"},
  {inf:"gehören", pres:"gehört", pra:"gehörte", perf:"hat gehört", it:"appartenere", en:"to belong", ex:[["Das Buch gehört mir.","Il libro è mio."],["Er gehört zu unserem Team.","Fa parte della nostra squadra."]], enex:[["Das Buch gehört mir.","The book is mine."],["Er gehört zu unserem Team.","He belongs to our team."]], note:"jdm gehören = essere di qualcuno (dativo, senza preposizione). zu jdm/etw gehören = far parte di.", enNote:"jdm gehören = to belong to someone (dative, no preposition). zu jdm/etw gehören = to be part of.", cat:"quotidiano"},
  {inf:"pflücken", pres:"pflückt", pra:"pflückte", perf:"hat gepflückt", it:"cogliere / raccogliere", en:"to pick", ex:[["Wir pflücken Äpfel im Garten.","Cogliamo mele in giardino."]], enex:[["Wir pflücken Äpfel im Garten.","We're picking apples in the garden."]], note:"etw Akk pflücken. Si usa per frutti e fiori.", enNote:"etw Akk pflücken. Used for fruit and flowers.", cat:"quotidiano"},
  {inf:"hören", pres:"hört", pra:"hörte", perf:"hat gehört", it:"sentire / udire", en:"to hear", ex:[["Ich höre die Musik.","Sento la musica."]], enex:[["Ich höre die Musik.","I hear the music."]], note:"jdn/etw Akk hören. Percezione involontaria; zuhören = ascoltare con attenzione. Con un secondo verbo: Ich habe sie telefonieren hören (nel parlato anche gehört).", enNote:"jdn/etw Akk hören. Involuntary perception; zuhören = to listen attentively. With a second verb: Ich habe sie telefonieren hören (colloquially also gehört).", cat:"percezione"},
  {inf:"zufügen", pres:"fügt zu", pra:"fügte zu", perf:"hat zugefügt", it:"infliggere / arrecare", en:"to inflict / to cause", ex:[["Er hat ihr Schaden zugefügt.","Le ha arrecato un danno."]], enex:[["Er hat ihr Schaden zugefügt.","He caused her harm."]], note:"Separabile. jdm etw Akk zufügen — la persona va al dativo.", enNote:"Separable. jdm etw Akk zufügen — the person goes in the dative.", cat:"quotidiano"},
  {inf:"erstatten", pres:"erstattet", pra:"erstattete", perf:"hat erstattet", it:"rimborsare / rifondere", en:"to reimburse / to refund", ex:[["Die Firma erstattet mir die Kosten.","L'azienda mi rimborsa le spese."]], enex:[["Die Firma erstattet mir die Kosten.","The company reimburses my costs."]], note:"jdm etw Akk erstatten. Anche: Anzeige erstatten = sporgere denuncia.", enNote:"jdm etw Akk erstatten. Also: Anzeige erstatten = to file a report.", cat:"lavoro"},
  {inf:"ersetzen", pres:"ersetzt", pra:"ersetzte", perf:"hat ersetzt", it:"sostituire / rimpiazzare", en:"to replace", ex:[["Wir ersetzen das alte Gerät.","Sostituiamo il vecchio apparecchio."]], enex:[["Wir ersetzen das alte Gerät.","We're replacing the old device."]], note:"jdn/etw Akk ersetzen. Sostantivo: der Ersatz.", enNote:"jdn/etw Akk ersetzen. Noun: der Ersatz.", cat:"quotidiano"},
  {inf:"vereinbaren", pres:"vereinbart", pra:"vereinbarte", perf:"hat vereinbart", it:"concordare / pattuire", en:"to agree on / to arrange", ex:[["Wir haben einen Termin vereinbart.","Abbiamo concordato un appuntamento."]], enex:[["Wir haben einen Termin vereinbart.","We arranged an appointment."]], note:"etw Akk vereinbaren. Aggettivo derivato: vereinbar = compatibile.", enNote:"etw Akk vereinbaren. Derived adjective: vereinbar = compatible.", cat:"lavoro"},
  {inf:"rühren", pres:"rührt", pra:"rührte", perf:"hat gerührt", it:"mescolare", en:"to stir", ex:[["Rühr die Suppe bitte um.","Mescola la zuppa, per favore."]], enex:[["Rühr die Suppe bitte um.","Please stir the soup."]], note:"etw Akk rühren. In senso figurato: commuovere (Das rührt mich).", enNote:"etw Akk rühren. Figuratively: to move emotionally (Das rührt mich).", cat:"quotidiano"},
  {inf:"hupen", pres:"hupt", pra:"hupte", perf:"hat gehupt", it:"clacsonare / suonare il clacson", en:"to honk", ex:[["Der Fahrer hupte laut.","L'autista suonò forte il clacson."]], enex:[["Der Fahrer hupte laut.","The driver honked loudly."]], note:"Intransitivo. Sostantivo: die Hupe = il clacson.", enNote:"Intransitive. Noun: die Hupe = the horn.", cat:"quotidiano"},
  {inf:"unterrichten", pres:"unterrichtet", pra:"unterrichtete", perf:"hat unterrichtet", it:"insegnare / istruire", en:"to teach", ex:[["Sie unterrichtet Deutsch.","Lei insegna tedesco."]], enex:[["Sie unterrichtet Deutsch.","She teaches German."]], note:"jdn in etw Dat unterrichten. Inseparabile: nessun ge- al participio. Sostantivo: der Unterricht.", enNote:"jdn in etw Dat unterrichten. Inseparable: no ge- in the participle. Noun: der Unterricht.", cat:"comunicazione"},
  {inf:"ernähren", pres:"ernährt", pra:"ernährte", perf:"hat ernährt", it:"nutrire / sfamare", en:"to feed / to nourish", ex:[["Er ernährt seine Familie.","Mantiene la sua famiglia."],["Ich ernähre mich gesund.","Mi alimento in modo sano."]], enex:[["Er ernährt seine Familie.","He provides for his family."],["Ich ernähre mich gesund.","I eat healthily."]], note:"jdn ernähren; sich Akk ernähren = alimentarsi. Sostantivo: die Ernährung.", enNote:"jdn ernähren; sich Akk ernähren = to eat/feed oneself. Noun: die Ernährung.", cat:"quotidiano"},
  {inf:"sich verhalten", pres:"verhält sich", pra:"verhielt sich", perf:"hat sich verhalten", it:"comportarsi", en:"to behave", ex:[["Er hat sich sehr höflich verhalten.","Si è comportato in modo molto gentile."]], enex:[["Er hat sich sehr höflich verhalten.","He behaved very politely."]], note:"sich Akk verhalten. Cambia a→ä al presente. Sostantivo: das Verhalten.", enNote:"sich Akk verhalten. Vowel changes a→ä in the present. Noun: das Verhalten.", cat:"riflessivo"},
  {inf:"vorstellen", pres:"stellt vor", pra:"stellte vor", perf:"hat vorgestellt", it:"presentare / immaginarsi", en:"to introduce / to imagine", ex:[["Darf ich Ihnen meinen Kollegen vorstellen?","Posso presentarle il mio collega?"],["Ich stelle mir das schwierig vor.","Me lo immagino difficile."],["Ich habe mir das Leben in Basel anders vorgestellt.","Mi ero immaginato la vita a Basilea diversamente."]], enex:[["Darf ich Ihnen meinen Kollegen vorstellen?","May I introduce my colleague to you?"],["Ich stelle mir das schwierig vor.","I imagine that to be difficult."],["Ich habe mir das Leben in Basel anders vorgestellt.","I had imagined life in Basel differently."]], note:"Separabile. jdn vorstellen = presentare (accusativo); sich Dat etw vorstellen = immaginarsi (dativo!).", enNote:"Separable. jdn vorstellen = to introduce (accusative); sich Dat etw vorstellen = to imagine (dative!).", cat:"comunicazione"},
  {inf:"üben", pres:"übt", pra:"übte", perf:"hat geübt", it:"esercitarsi / fare pratica", en:"to practise", ex:[["Ich übe jeden Tag Deutsch.","Mi esercito ogni giorno col tedesco."]], enex:[["Ich übe jeden Tag Deutsch.","I practise German every day."]], note:"etw Akk üben; sich Akk in etw Dat üben. Sostantivo: die Übung.", enNote:"etw Akk üben; sich Akk in etw Dat üben. Noun: die Übung.", cat:"mentale"},
  {inf:"studieren", pres:"studiert", pra:"studierte", perf:"hat studiert", it:"studiare (all'università)", en:"to study (at university)", ex:[["Sie studiert Medizin in Berlin.","Studia medicina a Berlino."]], enex:[["Sie studiert Medizin in Berlin.","She studies medicine in Berlin."]], note:"Solo per gli studi universitari. Per tutto il resto (scuola, lingue, per un esame) si usa lernen.", enNote:"Only for university studies. For everything else (school, languages, for an exam) use lernen.", cat:"mentale"},
  {inf:"umleiten", pres:"leitet um", pra:"leitete um", perf:"hat umgeleitet", it:"deviare / dirottare", en:"to divert / to reroute", ex:[["Der Verkehr wird umgeleitet.","Il traffico viene deviato."]], enex:[["Der Verkehr wird umgeleitet.","Traffic is being diverted."]], note:"Separabile. etw/jdn umleiten.", enNote:"Separable. etw/jdn umleiten.", cat:"movimento"},
  {inf:"treten", pres:"tritt", pra:"trat", perf:"hat/ist getreten", it:"calciare / mettere piede", en:"to kick / to step", ex:[["Er hat den Ball getreten.","Ha calciato il pallone."],["Sie ist ins Zimmer getreten.","È entrata nella stanza."]], enex:[["Er hat den Ball getreten.","He kicked the ball."],["Sie ist ins Zimmer getreten.","She stepped into the room."]], note:"hat getreten = calciare (transitivo); ist getreten = fare un passo, entrare (movimento).", enNote:"hat getreten = to kick (transitive); ist getreten = to step, to enter (motion).", cat:"movimento"},
  {inf:"herzeigen", pres:"zeigt her", pra:"zeigte her", perf:"hat hergezeigt", it:"mostrare / far vedere", en:"to show / to display", ex:[["Zeig mal her, was du gekauft hast!","Fammi vedere cosa hai comprato!"]], enex:[["Zeig mal her, was du gekauft hast!","Show me what you bought!"]], note:"Separabile e colloquiale. Più neutro: zeigen.", enNote:"Separable and colloquial. More neutral: zeigen.", cat:"comunicazione"},
  {inf:"erschöpfen", pres:"erschöpft", pra:"erschöpfte", perf:"hat erschöpft", it:"sfiancare / spossare", en:"to exhaust", ex:[["Die Reise hat mich erschöpft.","Il viaggio mi ha sfiancato."]], enex:[["Die Reise hat mich erschöpft.","The journey exhausted me."]], note:"etw/jdn erschöpfen. Il participio erschöpft si usa come aggettivo = esausto.", enNote:"etw/jdn erschöpfen. The participle erschöpft is used as an adjective = exhausted.", cat:"quotidiano"},
  {inf:"wehtun", pres:"tut weh", pra:"tat weh", perf:"hat wehgetan", it:"far male / farsi male", en:"to hurt", ex:[["Mein Rücken tut mir weh.","Mi fa male la schiena."],["Ich habe mir wehgetan.","Mi sono fatto male."]], enex:[["Mein Rücken tut mir weh.","My back hurts."],["Ich habe mir wehgetan.","I hurt myself."]], note:"Separabile. jdm wehtun — la persona va sempre al DATIVO, anche riflessivo: sich Dat wehtun.", enNote:"Separable. jdm wehtun — the person is always in the DATIVE, including reflexively: sich Dat wehtun.", cat:"quotidiano"},
  {inf:"vermeiden", pres:"vermeidet", pra:"vermied", perf:"hat vermieden", it:"evitare", en:"to avoid", ex:[["Ich vermeide den Verkehr am Morgen.","Evito il traffico la mattina."]], enex:[["Ich vermeide den Verkehr am Morgen.","I avoid the traffic in the morning."]], note:"etw/jdn Akk vermeiden = evitare di incontrare o di fare. Diverso da verhindern = impedire che accada.", enNote:"etw/jdn Akk vermeiden = to avoid meeting or doing. Different from verhindern = to prevent something happening.", cat:"quotidiano"},
  {inf:"zustimmen", pres:"stimmt zu", pra:"stimmte zu", perf:"hat zugestimmt", it:"essere d'accordo / acconsentire", en:"to agree / to consent", ex:[["Ich stimme dir zu.","Sono d'accordo con te."]], enex:[["Ich stimme dir zu.","I agree with you."]], note:"Separabile. jdm/etw Dat zustimmen — regge il DATIVO senza preposizione.", enNote:"Separable. jdm/etw Dat zustimmen — takes the DATIVE with no preposition.", cat:"comunicazione"},
  {inf:"abwägen", pres:"wägt ab", pra:"wog ab", perf:"hat abgewogen", it:"ponderare / soppesare", en:"to weigh up / to consider", ex:[["Wir müssen die Vorteile und Nachteile abwägen.","Dobbiamo ponderare i vantaggi e gli svantaggi."]], enex:[["Wir müssen die Vorteile und Nachteile abwägen.","We have to weigh up the pros and cons."]], note:"Separabile, forte (come wiegen). etw Akk abwägen — è il pesare mentale, non fisico.", enNote:"Separable, strong (like wiegen). etw Akk abwägen — mental weighing, not physical.", cat:"mentale"},
  {inf:"herstellen", pres:"stellt her", pra:"stellte her", perf:"hat hergestellt", it:"produrre / fabbricare", en:"to produce / to manufacture", ex:[["Die Firma stellt Möbel her.","L'azienda produce mobili."]], enex:[["Die Firma stellt Möbel her.","The company manufactures furniture."]], note:"Separabile. etw Akk herstellen. Sostantivo: der Hersteller = il produttore.", enNote:"Separable. etw Akk herstellen. Noun: der Hersteller = the manufacturer.", cat:"lavoro"},
  {inf:"aufnehmen", pres:"nimmt auf", pra:"nahm auf", perf:"hat aufgenommen", it:"raccogliere / accogliere / registrare", en:"to pick up / to take in / to record", ex:[["Sie haben uns freundlich aufgenommen.","Ci hanno accolti cordialmente."],["Ich nehme das Gespräch auf.","Registro la conversazione."]], enex:[["Sie haben uns freundlich aufgenommen.","They welcomed us warmly."],["Ich nehme das Gespräch auf.","I'm recording the conversation."]], note:"Separabile. jdn/etw aufnehmen — accogliere, assorbire, ma anche registrare audio o video.", enNote:"Separable. jdn/etw aufnehmen — to take in, absorb, but also to record audio or video.", cat:"quotidiano"},
  {inf:"verändern", pres:"verändert", pra:"veränderte", perf:"hat verändert", it:"cambiare / modificare", en:"to change / to alter", ex:[["Das hat mein Leben verändert.","Questo ha cambiato la mia vita."]], enex:[["Das hat mein Leben verändert.","That changed my life."]], note:"etw/jdn verändern = cambiare qualcosa; sich Akk verändern = cambiare (riferito a sé). Diverso da wechseln = scambiare, sostituire.", enNote:"etw/jdn verändern = to change something; sich Akk verändern = to change (oneself). Different from wechseln = to swap, to switch.", cat:"quotidiano"},
  {inf:"reifen", pres:"reift", pra:"reifte", perf:"ist gereift", it:"maturare / stagionare", en:"to ripen / to mature", ex:[["Der Käse reift sechs Monate.","Il formaggio stagiona sei mesi."]], enex:[["Der Käse reift sechs Monate.","The cheese matures for six months."]], note:"Usa sein al Perfekt (cambiamento di stato). Aggettivo: reif = maturo.", enNote:"Takes sein in the Perfekt (change of state). Adjective: reif = ripe.", cat:"quotidiano"},
  {inf:"aufpassen", pres:"passt auf", pra:"passte auf", perf:"hat aufgepasst", it:"fare attenzione / badare", en:"to pay attention / to look after", ex:[["Pass auf die Kinder auf!","Bada ai bambini!"]], enex:[["Pass auf die Kinder auf!","Look after the children!"]], note:"Separabile. auf jdn/etw Akk aufpassen.", enNote:"Separable. auf jdn/etw Akk aufpassen.", cat:"quotidiano"},
  {inf:"beraten", pres:"berät", pra:"beriet", perf:"hat beraten", it:"consigliare / consultarsi", en:"to advise / to confer", ex:[["Der Anwalt berät mich.","L'avvocato mi consiglia."],["Wir beraten uns darüber.","Ci consultiamo al riguardo."]], enex:[["Der Anwalt berät mich.","The lawyer advises me."],["Wir beraten uns darüber.","We're conferring about it."]], note:"jdn beraten = dare consigli (accusativo); sich Akk beraten = consultarsi. Cambia a→ä al presente.", enNote:"jdn beraten = to advise someone (accusative); sich Akk beraten = to confer. Vowel changes a→ä in the present.", cat:"comunicazione"},
  {inf:"holen", pres:"holt", pra:"holte", perf:"hat geholt", it:"andare a prendere", en:"to fetch / to get", ex:[["Ich hole dir ein Glas Wasser.","Ti vado a prendere un bicchiere d'acqua."]], enex:[["Ich hole dir ein Glas Wasser.","I'll fetch you a glass of water."]], note:"jdm etw Akk holen. Implica muoversi per andare a prendere, diverso da nehmen.", enNote:"jdm etw Akk holen. Implies moving to go and get it, unlike nehmen.", cat:"movimento"},
  {inf:"verbringen", pres:"verbringt", pra:"verbrachte", perf:"hat verbracht", it:"trascorrere / passare (tempo)", en:"to spend (time)", ex:[["Wir verbringen den Sommer am Meer.","Trascorriamo l'estate al mare."]], enex:[["Wir verbringen den Sommer am Meer.","We spend the summer at the sea."]], note:"Solo per il TEMPO. Per i soldi si usa ausgeben. Verbo misto: verbrachte, verbracht.", enNote:"Only for TIME. For money use ausgeben. Mixed verb: verbrachte, verbracht.", cat:"quotidiano"},
  {inf:"achten", pres:"achtet", pra:"achtete", perf:"hat geachtet", it:"far caso / stare attento", en:"to pay attention / to mind", ex:[["Achte auf die Stufe!","Attento al gradino!"]], enex:[["Achte auf die Stufe!","Mind the step!"]], note:"auf jdn/etw Akk achten. Senza preposizione, jdn achten = stimare qualcuno.", enNote:"auf jdn/etw Akk achten. Without a preposition, jdn achten = to respect someone.", cat:"mentale"},
  {inf:"leiden", pres:"leidet", pra:"litt", perf:"hat gelitten", it:"soffrire / penare", en:"to suffer", ex:[["Er leidet unter dem Stress.","Soffre a causa dello stress."]], enex:[["Er leidet unter dem Stress.","He suffers from the stress."]], note:"unter etw Dat leiden = soffrire a causa di; an etw Dat leiden = soffrire di (malattia). Sostantivo: das Leiden.", enNote:"unter etw Dat leiden = to suffer because of; an etw Dat leiden = to suffer from (illness). Noun: das Leiden.", cat:"quotidiano"},
  {inf:"einkaufen", pres:"kauft ein", pra:"kaufte ein", perf:"hat eingekauft", it:"fare la spesa / acquistare", en:"to shop / to buy in", ex:[["Ich kaufe am Samstag ein.","Faccio la spesa il sabato."]], enex:[["Ich kaufe am Samstag ein.","I do the shopping on Saturday."]], note:"Separabile. Senza oggetto = fare la spesa; con oggetto etw Akk einkaufen = acquistare.", enNote:"Separable. Without an object = to do the shopping; with an object etw Akk einkaufen = to purchase.", cat:"quotidiano"},
  {inf:"verbrauchen", pres:"verbraucht", pra:"verbrauchte", perf:"hat verbraucht", it:"consumare", en:"to consume / to use up", ex:[["Das Auto verbraucht viel Benzin.","L'auto consuma molta benzina."]], enex:[["Das Auto verbraucht viel Benzin.","The car uses a lot of petrol."]], note:"etw Akk verbrauchen — consumare fino a esaurire. Sostantivo: der Verbraucher = il consumatore.", enNote:"etw Akk verbrauchen — to use up completely. Noun: der Verbraucher = the consumer.", cat:"quotidiano"},
  {inf:"erzeugen", pres:"erzeugt", pra:"erzeugte", perf:"hat erzeugt", it:"produrre / generare", en:"to produce / to generate", ex:[["Die Anlage erzeugt Strom.","L'impianto produce elettricità."]], enex:[["Die Anlage erzeugt Strom.","The plant generates electricity."]], note:"etw Akk erzeugen — più astratto di herstellen: energia, effetti, sensazioni.", enNote:"etw Akk erzeugen — more abstract than herstellen: energy, effects, feelings.", cat:"lavoro"},
  {inf:"benutzen", pres:"benutzt", pra:"benutzte", perf:"hat benutzt", it:"usare / utilizzare", en:"to use", ex:[["Ich benutze den Bus jeden Tag.","Uso l'autobus ogni giorno."]], enex:[["Ich benutze den Bus jeden Tag.","I use the bus every day."]], note:"etw Akk benutzen. In Germania del sud e Austria anche benützen.", enNote:"etw Akk benutzen. In southern Germany and Austria also benützen.", cat:"quotidiano"},
  {inf:"verzichten", pres:"verzichtet", pra:"verzichtete", perf:"hat verzichtet", it:"rinunciare", en:"to give up / to do without", ex:[["Ich verzichte auf den Nachtisch.","Rinuncio al dessert."]], enex:[["Ich verzichte auf den Nachtisch.","I'll do without dessert."]], note:"auf etw Akk verzichten — sempre con auf + accusativo.", enNote:"auf etw Akk verzichten — always with auf + accusative.", cat:"mentale"},
  {inf:"verhindern", pres:"verhindert", pra:"verhinderte", perf:"hat verhindert", it:"impedire / evitare", en:"to prevent", ex:[["Wir konnten den Unfall nicht verhindern.","Non siamo riusciti a evitare l'incidente."]], enex:[["Wir konnten den Unfall nicht verhindern.","We couldn't prevent the accident."]], note:"etw Akk verhindern = fare in modo che non accada. Diverso da vermeiden = evitare, stare alla larga.", enNote:"etw Akk verhindern = to stop something from happening. Different from vermeiden = to steer clear of.", cat:"quotidiano"},
  {inf:"teilnehmen", pres:"nimmt teil", pra:"nahm teil", perf:"hat teilgenommen", it:"partecipare", en:"to take part / to participate", ex:[["Sie nimmt an dem Kurs teil.","Partecipa al corso."]], enex:[["Sie nimmt an dem Kurs teil.","She's taking part in the course."]], note:"Separabile. an etw Dat teilnehmen — sempre an + DATIVO.", enNote:"Separable. an etw Dat teilnehmen — always an + DATIVE.", cat:"quotidiano"},
  {inf:"vorhaben", pres:"hat vor", pra:"hatte vor", perf:"hat vorgehabt", it:"avere in programma / avere intenzione", en:"to plan / to intend", ex:[["Was hast du am Wochenende vor?","Cosa hai in programma per il fine settimana?"]], enex:[["Was hast du am Wochenende vor?","What are you planning for the weekend?"]], note:"Separabile da haben. etw Akk vorhaben. Sostantivo: das Vorhaben = il progetto.", enNote:"Separable, based on haben. etw Akk vorhaben. Noun: das Vorhaben = the plan.", cat:"mentale"},
  {inf:"verabreden", pres:"verabredet", pra:"verabredete", perf:"hat verabredet", it:"concordare / darsi appuntamento", en:"to arrange / to make a date", ex:[["Wir haben uns für morgen verabredet.","Ci siamo dati appuntamento per domani."]], enex:[["Wir haben uns für morgen verabredet.","We arranged to meet tomorrow."]], note:"etw Akk verabreden; sich Akk mit jdm verabreden = darsi appuntamento.", enNote:"etw Akk verabreden; sich Akk mit jdm verabreden = to arrange to meet.", cat:"comunicazione"},
  {inf:"entfernen", pres:"entfernt", pra:"entfernte", perf:"hat entfernt", it:"togliere / allontanare", en:"to remove / to take away", ex:[["Bitte entfernen Sie den Fleck.","Per favore tolga la macchia."]], enex:[["Bitte entfernen Sie den Fleck.","Please remove the stain."]], note:"jdn/etw Akk entfernen; sich Akk entfernen = allontanarsi. Sostantivo: das Entfernen; aggettivo: entfernt = distante.", enNote:"jdn/etw Akk entfernen; sich Akk entfernen = to move away. Noun: das Entfernen; adjective: entfernt = distant.", cat:"quotidiano"},
  {inf:"anklagen", pres:"klagt an", pra:"klagte an", perf:"hat angeklagt", it:"accusare", en:"to accuse / to charge", ex:[["Man klagt ihn wegen Diebstahls an.","Lo accusano di furto."]], enex:[["Man klagt ihn wegen Diebstahls an.","He is being charged with theft."]], note:"Separabile. jdn wegen etw Gen anklagen — termine giuridico.", enNote:"Separable. jdn wegen etw Gen anklagen — a legal term.", cat:"comunicazione"},
  {inf:"unterstützen", pres:"unterstützt", pra:"unterstützte", perf:"hat unterstützt", it:"sostenere / supportare", en:"to support", ex:[["Meine Familie unterstützt mich.","La mia famiglia mi sostiene."]], enex:[["Meine Familie unterstützt mich.","My family supports me."]], note:"jdn/etw Akk unterstützen. Inseparabile: nessun ge- al participio.", enNote:"jdn/etw Akk unterstützen. Inseparable: no ge- in the participle.", cat:"quotidiano"},
  {inf:"besichtigen", pres:"besichtigt", pra:"besichtigte", perf:"hat besichtigt", it:"visitare / fare un sopralluogo", en:"to visit / to view", ex:[["Wir besichtigen morgen die Wohnung.","Domani visitiamo l'appartamento."]], enex:[["Wir besichtigen morgen die Wohnung.","We're viewing the flat tomorrow."]], note:"etw Akk besichtigen — visitare un luogo o un edificio. Per le persone si usa besuchen.", enNote:"etw Akk besichtigen — to visit a place or building. For people use besuchen.", cat:"movimento"},
  {inf:"umzingeln", pres:"umzingelt", pra:"umzingelte", perf:"hat umzingelt", it:"accerchiare / assediare", en:"to surround / to encircle", ex:[["Die Polizei hat das Haus umzingelt.","La polizia ha accerchiato la casa."]], enex:[["Die Polizei hat das Haus umzingelt.","The police surrounded the house."]], note:"jdn/etw Akk umzingeln. Inseparabile: nessun ge- al participio.", enNote:"jdn/etw Akk umzingeln. Inseparable: no ge- in the participle.", cat:"movimento"},
  {inf:"sich anstrengen", pres:"strengt sich an", pra:"strengte sich an", perf:"hat sich angestrengt", it:"sforzarsi / affaticarsi", en:"to make an effort / to exert oneself", ex:[["Du musst dich mehr anstrengen.","Devi sforzarti di più."]], enex:[["Du musst dich mehr anstrengen.","You have to make more of an effort."]], note:"Separabile e riflessivo all'accusativo. Aggettivo: anstrengend = faticoso.", enNote:"Separable and reflexive in the accusative. Adjective: anstrengend = tiring.", cat:"riflessivo"},
  {inf:"zweifeln", pres:"zweifelt", pra:"zweifelte", perf:"hat gezweifelt", it:"dubitare", en:"to doubt", ex:[["Ich zweifle an seiner Ehrlichkeit.","Dubito della sua onestà."]], enex:[["Ich zweifle an seiner Ehrlichkeit.","I doubt his honesty."]], note:"an jdm/etw Dat zweifeln — sempre an + DATIVO. Sostantivo: der Zweifel.", enNote:"an jdm/etw Dat zweifeln — always an + DATIVE. Noun: der Zweifel.", cat:"mentale"},
  {inf:"bügeln", pres:"bügelt", pra:"bügelte", perf:"hat gebügelt", it:"stirare", en:"to iron", ex:[["Ich bügle die Hemden.","Stiro le camicie."]], enex:[["Ich bügle die Hemden.","I'm ironing the shirts."]], note:"etw Akk bügeln. Attenzione: der Bügel = la gruccia, das Bügeleisen = il ferro da stiro.", enNote:"etw Akk bügeln. Note: der Bügel = the coat hanger, das Bügeleisen = the iron.", cat:"quotidiano"},
  {inf:"wesen", pres:"west", pra:"weste", perf:"ist gewest", it:"essere / esistere", en:"to be / to exist", ex:[["Ein Geist west in diesem Haus.","Uno spirito abita in questa casa."]], enex:[["Ein Geist west in diesem Haus.","A spirit dwells in this house."]], note:"Verbo desueto e formale: oggi si usa sein. Resta vivo nei composti (anwesend, abwesend, verwesen) e nel sostantivo das Wesen.", enNote:"Obsolete and formal verb: today sein is used. It survives in compounds (anwesend, abwesend, verwesen) and in the noun das Wesen.", cat:"ausiliare"},
  {inf:"an etwas liegen", pres:"liegt an", pra:"lag an", perf:"hat gelegen", it:"dipendere da", en:"to be due to / to depend on", ex:[["Es liegt am Wetter.","Dipende dal tempo."]], enex:[["Es liegt am Wetter.","It's down to the weather."]], note:"an jdm/etw Dat liegen — sempre impersonale con es. Diverso da liegen = essere sdraiato.", enNote:"an jdm/etw Dat liegen — always impersonal with es. Different from liegen = to lie down.", cat:"posizione"},
  {inf:"enttäuschen", pres:"enttäuscht", pra:"enttäuschte", perf:"hat enttäuscht", it:"deludere", en:"to disappoint", ex:[["Das Ergebnis hat mich enttäuscht.","Il risultato mi ha deluso."]], enex:[["Das Ergebnis hat mich enttäuscht.","The result disappointed me."]], note:"jdn/etw Akk enttäuschen. Il participio enttäuscht si usa come aggettivo = deluso.", enNote:"jdn/etw Akk enttäuschen. The participle enttäuscht is used as an adjective = disappointed.", cat:"quotidiano"},
  {inf:"abnehmen", pres:"nimmt ab", pra:"nahm ab", perf:"hat abgenommen", it:"dimagrire / diminuire", en:"to lose weight / to decrease", ex:[["Ich habe fünf Kilo abgenommen.","Ho perso cinque chili."]], enex:[["Ich habe fünf Kilo abgenommen.","I've lost five kilos."]], note:"Separabile. Contrario: zunehmen = ingrassare, aumentare. Anche: den Hörer abnehmen = rispondere al telefono.", enNote:"Separable. Opposite: zunehmen = to gain weight, to increase. Also: den Hörer abnehmen = to pick up the phone.", cat:"quotidiano"},
  {inf:"abbauen", pres:"baut ab", pra:"baute ab", perf:"hat abgebaut", it:"smontare / demolire", en:"to dismantle / to reduce", ex:[["Wir bauen das Zelt ab.","Smontiamo la tenda."]], enex:[["Wir bauen das Zelt ab.","We're taking down the tent."]], note:"Separabile. etw Akk abbauen. Anche figurato: Stress abbauen = ridurre lo stress.", enNote:"Separable. etw Akk abbauen. Also figurative: Stress abbauen = to reduce stress.", cat:"lavoro"},
  {inf:"bauen", pres:"baut", pra:"baute", perf:"hat gebaut", it:"costruire", en:"to build", ex:[["Sie bauen ein neues Haus.","Costruiscono una casa nuova."]], enex:[["Sie bauen ein neues Haus.","They're building a new house."]], note:"etw Akk bauen. Anche: auf jdn bauen = contare su qualcuno.", enNote:"etw Akk bauen. Also: auf jdn bauen = to count on someone.", cat:"lavoro"},
  {inf:"sich entschließen", pres:"entschließt sich", pra:"entschloss sich", perf:"hat sich entschlossen", it:"decidersi / risolversi", en:"to make up one's mind", ex:[["Ich habe mich zu einem Umzug entschlossen.","Mi sono deciso a traslocare."]], enex:[["Ich habe mich zu einem Umzug entschlossen.","I made up my mind to move house."]], note:"sich Akk zu etw Dat entschließen — decisione ponderata dopo riflessione. Aggettivo: entschlossen = deciso.", enNote:"sich Akk zu etw Dat entschließen — a considered decision after reflection. Adjective: entschlossen = determined.", cat:"riflessivo"},
  {inf:"ankommen", pres:"kommt an", pra:"kam an", perf:"ist angekommen", it:"arrivare", en:"to arrive", ex:[["Der Zug kommt um 8 Uhr an.","Il treno arriva alle 8."]], enex:[["Der Zug kommt um 8 Uhr an.","The train arrives at 8."]], note:"Separabile, con sein. Con preposizione: ankommen auf + Akk = dipendere da — Es kommt auf das Wetter an, ob wir einen Ausflug machen.", enNote:"Separable, with sein. With a preposition: ankommen auf + Akk = to depend on — Es kommt auf das Wetter an, ob wir einen Ausflug machen.", cat:"verbi con preposizione"},
  {inf:"sich ärgern", pres:"ärgert sich", pra:"ärgerte sich", perf:"hat sich geärgert", it:"arrabbiarsi", en:"to get annoyed", ex:[["Herr Klinke ärgert sich über den Lärm in der Klasse.","Il signor Klinke si arrabbia per il rumore in classe."]], enex:[["Herr Klinke ärgert sich über den Lärm in der Klasse.","Mr Klinke gets annoyed about the noise in class."]], note:"sich ärgern über + Akk. Il motivo della rabbia va sempre con über.", enNote:"sich ärgern über + Akk. The reason for the anger always takes über.", cat:"verbi con preposizione"},
  {inf:"bitten", pres:"bittet", pra:"bat", perf:"hat gebeten", it:"chiedere / pregare", en:"to ask for / to request", ex:[["Er hat höflich um eine Erklärung gebeten.","Ha chiesto gentilmente una spiegazione."]], enex:[["Er hat höflich um eine Erklärung gebeten.","He politely asked for an explanation."]], note:"Irregolare. jdn um etw Akk bitten: la persona in accusativo, la cosa con um. Non confondere con fragen (fare una domanda).", enNote:"Irregular. jdn um etw Akk bitten: the person in the accusative, the thing with um. Not to be confused with fragen (to ask a question).", cat:"verbi con preposizione"},
  {inf:"sich eignen", pres:"eignet sich", pra:"eignete sich", perf:"hat sich geeignet", it:"essere adatto", en:"to be suitable", ex:[["Die Themen Religion und Politik eignen sich nicht für Smalltalk.","I temi religione e politica non sono adatti alle chiacchiere."]], enex:[["Die Themen Religion und Politik eignen sich nicht für Smalltalk.","Religion and politics are not suitable topics for small talk."]], note:"sich eignen für + Akk. Anche: geeignet sein für = essere adatto a.", enNote:"sich eignen für + Akk. Also: geeignet sein für = to be suited to.", cat:"verbi con preposizione"},
  {inf:"sich entscheiden", pres:"entscheidet sich", pra:"entschied sich", perf:"hat sich entschieden", it:"decidersi / scegliere", en:"to decide / to choose", ex:[["Er entscheidet sich für den blauen Pullover.","Sceglie il maglione blu."]], enex:[["Er entscheidet sich für den blauen Pullover.","He chooses the blue jumper."]], note:"Irregolare. sich entscheiden für + Akk = scegliere fra alternative. Senza riflessivo: etw Akk entscheiden = decidere una questione.", enNote:"Irregular. sich entscheiden für + Akk = to choose between alternatives. Without the reflexive: etw Akk entscheiden = to settle a matter.", cat:"verbi con preposizione"},
  {inf:"sich entschuldigen", pres:"entschuldigt sich", pra:"entschuldigte sich", perf:"hat sich entschuldigt", it:"scusarsi", en:"to apologise", ex:[["Ich möchte mich für den Lärm entschuldigen.","Vorrei scusarmi per il rumore."],["Ich möchte mich bei Ihnen entschuldigen.","Vorrei scusarmi con Lei."]], enex:[["Ich möchte mich für den Lärm entschuldigen.","I'd like to apologise for the noise."],["Ich möchte mich bei Ihnen entschuldigen.","I'd like to apologise to you."]], note:"Due preposizioni insieme: für + Akk = per che cosa · bei + Dat = con chi.", enNote:"Two prepositions at once: für + Akk = what for · bei + Dat = to whom.", cat:"verbi con preposizione"},
  {inf:"sich erinnern", pres:"erinnert sich", pra:"erinnerte sich", perf:"hat sich erinnert", it:"ricordarsi", en:"to remember", ex:[["Fini erinnert sich gerne an die Konzerte auf dem Festival.","Fini ricorda volentieri i concerti al festival."]], enex:[["Fini erinnert sich gerne an die Konzerte auf dem Festival.","Fini likes remembering the concerts at the festival."]], note:"sich erinnern an + Akk. Senza riflessivo: jdn an etw erinnern = ricordare qualcosa a qualcuno.", enNote:"sich erinnern an + Akk. Without the reflexive: jdn an etw erinnern = to remind someone of something.", cat:"verbi con preposizione"},
  {inf:"sich freuen", pres:"freut sich", pra:"freute sich", perf:"hat sich gefreut", it:"essere contento / rallegrarsi", en:"to be glad / to look forward", ex:[["Dennis freut sich auf die Pause.","Dennis non vede l'ora della pausa."],["Laura freut sich über das Geschenk.","Laura è contenta del regalo."]], enex:[["Dennis freut sich auf die Pause.","Dennis is looking forward to the break."],["Laura freut sich über das Geschenk.","Laura is happy about the present."]], note:"La coppia da ricordare: auf + Akk = qualcosa che deve ancora arrivare · über + Akk = qualcosa che è già successo.", enNote:"The pair to remember: auf + Akk = something still to come · über + Akk = something that has already happened.", cat:"verbi con preposizione"},
  {inf:"sich gewöhnen", pres:"gewöhnt sich", pra:"gewöhnte sich", perf:"hat sich gewöhnt", it:"abituarsi", en:"to get used to", ex:[["Mohan kann sich nicht an die deutsche Direktheit gewöhnen.","Mohan non riesce ad abituarsi alla schiettezza tedesca."]], enex:[["Mohan kann sich nicht an die deutsche Direktheit gewöhnen.","Mohan can't get used to German directness."]], note:"sich gewöhnen an + Akk. Stato raggiunto: an etw gewöhnt sein = essere abituato a.", enNote:"sich gewöhnen an + Akk. Resulting state: an etw gewöhnt sein = to be used to.", cat:"verbi con preposizione"},
  {inf:"sich konzentrieren", pres:"konzentriert sich", pra:"konzentrierte sich", perf:"hat sich konzentriert", it:"concentrarsi", en:"to concentrate", ex:[["Ben kann sich schlecht auf den Unterricht konzentrieren.","Ben fatica a concentrarsi sulla lezione."]], enex:[["Ben kann sich schlecht auf den Unterricht konzentrieren.","Ben finds it hard to concentrate on the lesson."]], note:"sich konzentrieren auf + Akk.", enNote:"sich konzentrieren auf + Akk.", cat:"verbi con preposizione"},
  {inf:"sich kümmern", pres:"kümmert sich", pra:"kümmerte sich", perf:"hat sich gekümmert", it:"occuparsi / prendersi cura", en:"to take care of", ex:[["Ich muss mich um meinen Großvater kümmern.","Devo occuparmi di mio nonno."]], enex:[["Ich muss mich um meinen Großvater kümmern.","I have to take care of my grandfather."]], note:"sich kümmern um + Akk. Vale sia per persone sia per faccende.", enNote:"sich kümmern um + Akk. Works for both people and tasks.", cat:"verbi con preposizione"},
  {inf:"nachdenken", pres:"denkt nach", pra:"dachte nach", perf:"hat nachgedacht", it:"riflettere", en:"to think about / to reflect", ex:[["Ich habe lange über das Problem nachgedacht.","Ho riflettuto a lungo sul problema."]], enex:[["Ich habe lange über das Problem nachgedacht.","I thought about the problem for a long time."]], note:"Separabile e irregolare. nachdenken über + Akk = riflettere su. Diverso da denken an + Akk = pensare a (qualcuno).", enNote:"Separable and irregular. nachdenken über + Akk = to reflect on. Different from denken an + Akk = to think of (someone).", cat:"verbi con preposizione"},
  {inf:"reden", pres:"redet", pra:"redete", perf:"hat geredet", it:"parlare / chiacchierare", en:"to talk", ex:[["Meine Freundin redet immer über den Urlaub.","La mia amica parla sempre delle vacanze."],["Laura redet gern mit ihrer Freundin Selina.","Laura parla volentieri con la sua amica Selina."]], enex:[["Meine Freundin redet immer über den Urlaub.","My friend always talks about her holidays."],["Laura redet gern mit ihrer Freundin Selina.","Laura likes talking with her friend Selina."]], note:"über + Akk = di che cosa · mit + Dat = con chi. Più colloquiale di sprechen.", enNote:"über + Akk = what about · mit + Dat = with whom. More colloquial than sprechen.", cat:"verbi con preposizione"},
  {inf:"sorgen", pres:"sorgt", pra:"sorgte", perf:"hat gesorgt", it:"provvedere / occuparsi", en:"to provide for / to see to", ex:[["Die Frauen sorgten früher für Haushalt und Kinder.","Un tempo le donne si occupavano della casa e dei figli."]], enex:[["Die Frauen sorgten früher für Haushalt und Kinder.","Women used to take care of the household and the children."]], note:"sorgen für + Akk = provvedere a. Riflessivo: sich sorgen um + Akk = essere in pena per.", enNote:"sorgen für + Akk = to provide for. Reflexive: sich sorgen um + Akk = to worry about.", cat:"verbi con preposizione"},
  {inf:"sich vorbereiten", pres:"bereitet sich vor", pra:"bereitete sich vor", perf:"hat sich vorbereitet", it:"prepararsi", en:"to prepare", ex:[["Wir müssen uns auf die Prüfung vorbereiten.","Dobbiamo prepararci per l'esame."]], enex:[["Wir müssen uns auf die Prüfung vorbereiten.","We have to prepare for the exam."]], note:"Separabile. sich vorbereiten auf + Akk.", enNote:"Separable. sich vorbereiten auf + Akk.", cat:"verbi con preposizione"},
  {inf:"warten", pres:"wartet", pra:"wartete", perf:"hat gewartet", it:"aspettare", en:"to wait", ex:[["Wie lange warten Sie schon auf den Bus?","Da quanto aspetta l'autobus?"]], enex:[["Wie lange warten Sie schon auf den Bus?","How long have you been waiting for the bus?"]], note:"warten auf + Akk: in tedesco l'attesa vuole sempre la preposizione, anche quando l'italiano non la mette.", enNote:"warten auf + Akk: German always needs the preposition here.", cat:"verbi con preposizione"},
  {inf:"sich wenden", pres:"wendet sich", pra:"wandte sich", perf:"hat sich gewandt", it:"rivolgersi", en:"to turn to", ex:[["Bei Fragen können Sie sich gerne an mich wenden.","Per domande può rivolgersi tranquillamente a me."]], enex:[["Bei Fragen können Sie sich gerne an mich wenden.","If you have questions, feel free to turn to me."]], note:"sich wenden an + Akk. Forme deboli ammesse: wendete sich, hat sich gewendet.", enNote:"sich wenden an + Akk. Weak forms are also allowed: wendete sich, hat sich gewendet.", cat:"verbi con preposizione"},
  {inf:"sich wundern", pres:"wundert sich", pra:"wunderte sich", perf:"hat sich gewundert", it:"stupirsi", en:"to be surprised", ex:[["Mohan hat sich über das Essen in Deutschland gewundert.","Mohan si è stupito del cibo in Germania."]], enex:[["Mohan hat sich über das Essen in Deutschland gewundert.","Mohan was surprised by the food in Germany."]], note:"sich wundern über + Akk.", enNote:"sich wundern über + Akk.", cat:"verbi con preposizione"},
  {inf:"abhängen", pres:"hängt ab", pra:"hing ab", perf:"hat abgehangen", it:"dipendere", en:"to depend", ex:[["Mit wem man worüber spricht, hängt stark von der Situation ab.","Con chi si parla di che cosa dipende molto dalla situazione."]], enex:[["Mit wem man worüber spricht, hängt stark von der Situation ab.","Who you talk to about what depends a lot on the situation."]], note:"Separabile e irregolare. abhängen von + Dat. Aggettivo: abhängig von = dipendente da.", enNote:"Separable and irregular. abhängen von + Dat. Adjective: abhängig von = dependent on.", cat:"verbi con preposizione"},
  {inf:"sich bedanken", pres:"bedankt sich", pra:"bedankte sich", perf:"hat sich bedankt", it:"ringraziare", en:"to thank", ex:[["Laura bedankt sich bei ihrer Kollegin.","Laura ringrazia la sua collega."]], enex:[["Laura bedankt sich bei ihrer Kollegin.","Laura thanks her colleague."]], note:"sich bedanken bei + Dat (chi) für + Akk (che cosa). Più formale di danken + Dat.", enNote:"sich bedanken bei + Dat (whom) für + Akk (what for). More formal than danken + Dat.", cat:"verbi con preposizione"},
  {inf:"beitragen", pres:"trägt bei", pra:"trug bei", perf:"hat beigetragen", it:"contribuire", en:"to contribute", ex:[["Die Migranten haben zum Erfolg der Wirtschaft beigetragen.","I migranti hanno contribuito al successo dell'economia."]], enex:[["Die Migranten haben zum Erfolg der Wirtschaft beigetragen.","Migrants have contributed to the success of the economy."]], note:"Separabile e irregolare. beitragen zu + Dat (zu dem → zum).", enNote:"Separable and irregular. beitragen zu + Dat (zu dem → zum).", cat:"verbi con preposizione"},
  {inf:"sich beteiligen", pres:"beteiligt sich", pra:"beteiligte sich", perf:"hat sich beteiligt", it:"partecipare / prendere parte", en:"to take part", ex:[["Wir beteiligen uns an einem Umweltprojekt.","Partecipiamo a un progetto ambientale."]], enex:[["Wir beteiligen uns an einem Umweltprojekt.","We are taking part in an environmental project."]], note:"sich beteiligen an + Dat. Sinonimo: teilnehmen an + Dat.", enNote:"sich beteiligen an + Dat. Synonym: teilnehmen an + Dat.", cat:"verbi con preposizione"},
  {inf:"berichten", pres:"berichtet", pra:"berichtete", perf:"hat berichtet", it:"riferire / raccontare", en:"to report", ex:[["Sie berichtet von ihrem Gespräch.","Racconta del suo colloquio."]], enex:[["Sie berichtet von ihrem Gespräch.","She reports on her conversation."]], note:"berichten von + Dat oppure über + Akk. Più formale di erzählen.", enNote:"berichten von + Dat or über + Akk. More formal than erzählen.", cat:"verbi con preposizione"},
  {inf:"sich beschäftigen", pres:"beschäftigt sich", pra:"beschäftigte sich", perf:"hat sich beschäftigt", it:"occuparsi", en:"to be busy with", ex:[["Jonas beschäftigt sich mit seinem Handy.","Jonas si sta occupando del suo cellulare."]], enex:[["Jonas beschäftigt sich mit seinem Handy.","Jonas is busy with his phone."]], note:"sich beschäftigen mit + Dat. Senza riflessivo: jdn beschäftigen = dare lavoro a qualcuno.", enNote:"sich beschäftigen mit + Dat. Without the reflexive: jdn beschäftigen = to employ someone.", cat:"verbi con preposizione"},
  {inf:"chatten", pres:"chattet", pra:"chattete", perf:"hat gechattet", it:"chattare", en:"to chat online", ex:[["Sonja chattet oft mit ihrer Freundin.","Sonja chatta spesso con la sua amica."]], enex:[["Sonja chattet oft mit ihrer Freundin.","Sonja often chats with her friend."]], note:"chatten mit + Dat. Prestito dall'inglese, coniugato come verbo debole tedesco.", enNote:"chatten mit + Dat. An English loanword, conjugated as a weak German verb.", cat:"verbi con preposizione"},
  {inf:"diskutieren", pres:"diskutiert", pra:"diskutierte", perf:"hat diskutiert", it:"discutere", en:"to discuss", ex:[["Katja diskutiert mit ihrer Freundin Saida.","Katja discute con la sua amica Saida."]], enex:[["Katja diskutiert mit ihrer Freundin Saida.","Katja is having a discussion with her friend Saida."]], note:"diskutieren mit + Dat (con chi) über + Akk (di che cosa). I verbi in -ieren non prendono ge- al Partizip.", enNote:"diskutieren mit + Dat (with whom) über + Akk (about what). Verbs in -ieren take no ge- in the past participle.", cat:"verbi con preposizione"},
  {inf:"sich erkundigen", pres:"erkundigt sich", pra:"erkundigte sich", perf:"hat sich erkundigt", it:"informarsi", en:"to enquire", ex:[["Er erkundigt sich nach dem Preis.","Si informa sul prezzo."]], enex:[["Er erkundigt sich nach dem Preis.","He enquires about the price."]], note:"sich erkundigen nach + Dat.", enNote:"sich erkundigen nach + Dat.", cat:"verbi con preposizione"},
  {inf:"passen", pres:"passt", pra:"passte", perf:"hat gepasst", it:"andare bene / addirsi", en:"to fit / to suit", ex:[["Die Stelle passt sehr gut zu ihr.","Il posto di lavoro le si addice molto."]], enex:[["Die Stelle passt sehr gut zu ihr.","The job suits her very well."]], note:"passen zu + Dat = armonizzare con. Attenzione: jdm passen (senza preposizione) = andare bene a qualcuno, di taglia o di orario.", enNote:"passen zu + Dat = to go well with. Note: jdm passen (no preposition) = to fit someone, of size or timing.", cat:"verbi con preposizione"},
  {inf:"sich streiten", pres:"streitet sich", pra:"stritt sich", perf:"hat sich gestritten", it:"litigare", en:"to quarrel", ex:[["Sie streitet sich mit ihrem Bruder.","Litiga con suo fratello."]], enex:[["Sie streitet sich mit ihrem Bruder.","She quarrels with her brother."]], note:"Irregolare. sich streiten mit + Dat (con chi) über/um + Akk (per che cosa). Si usa anche senza riflessivo: Sie streitet oft mit ihrem Bruder.", enNote:"Irregular. sich streiten mit + Dat (with whom) über/um + Akk (about what). Also used without the reflexive: Sie streitet oft mit ihrem Bruder.", cat:"verbi con preposizione"},
  {inf:"träumen", pres:"träumt", pra:"träumte", perf:"hat geträumt", it:"sognare", en:"to dream", ex:[["Dennis träumt von den Ferien.","Dennis sogna le vacanze."]], enex:[["Dennis träumt von den Ferien.","Dennis dreams of the holidays."]], note:"träumen von + Dat. Vale sia per il sogno notturno sia per il desiderio.", enNote:"träumen von + Dat. Used both for night dreams and for wishes.", cat:"verbi con preposizione"},
  {inf:"sich verabschieden", pres:"verabschiedet sich", pra:"verabschiedete sich", perf:"hat sich verabschiedet", it:"congedarsi / salutare", en:"to say goodbye", ex:[["Er verabschiedet sich von seinen Freunden.","Saluta i suoi amici prima di andare."]], enex:[["Er verabschiedet sich von seinen Freunden.","He says goodbye to his friends."]], note:"sich verabschieden von + Dat. È il saluto di chi se ne va; per quello di chi arriva si usa begrüßen.", enNote:"sich verabschieden von + Dat. This is the goodbye of someone leaving; for greeting on arrival use begrüßen.", cat:"verbi con preposizione"},
  {inf:"zählen", pres:"zählt", pra:"zählte", perf:"hat gezählt", it:"contare", en:"to count", ex:[["Zum ersten Eindruck zählt auch die Körpersprache.","Anche il linguaggio del corpo conta per la prima impressione."]], enex:[["Zum ersten Eindruck zählt auch die Körpersprache.","Body language also counts towards the first impression."]], note:"zählen zu + Dat = far parte di, rientrare fra. Senza preposizione: contare i numeri. Con auf + Akk: zählen auf jdn = contare su qualcuno.", enNote:"zählen zu + Dat = to be one of, to belong among. Without a preposition: to count numbers. With auf + Akk: zählen auf jdn = to count on someone.", cat:"verbi con preposizione"},
  {inf:"abfahren", pres:"fährt ab", pra:"fuhr ab", perf:"ist abgefahren", it:"partire", en:"to depart", ex:[["Der Zug fährt um acht Uhr ab.","Il treno parte alle otto."]], enex:[["Der Zug fährt um acht Uhr ab.","The train departs at eight."]], note:"Separabile, con sein. Il contrario di ankommen.", enNote:"Separable, with sein. The opposite of ankommen.", cat:"irregolare"},
  {inf:"abgeben", pres:"gibt ab", pra:"gab ab", perf:"hat abgegeben", it:"consegnare", en:"to hand in", ex:[["Ich muss die Hausaufgabe morgen abgeben.","Devo consegnare il compito domani."]], enex:[["Ich muss die Hausaufgabe morgen abgeben.","I have to hand in the homework tomorrow."]], note:"Separabile. etw Akk bei jdm abgeben.", enNote:"Separable. etw Akk bei jdm abgeben.", cat:"irregolare"},
  {inf:"abschließen", pres:"schließt ab", pra:"schloss ab", perf:"hat abgeschlossen", it:"chiudere a chiave / concludere", en:"to lock / to conclude", ex:[["Hast du die Tür abgeschlossen?","Hai chiuso a chiave la porta?"]], enex:[["Hast du die Tür abgeschlossen?","Did you lock the door?"]], note:"Separabile. Due sensi: chiudere a chiave, e portare a termine (einen Vertrag abschließen = stipulare un contratto).", enNote:"Separable. Two senses: to lock, and to complete (einen Vertrag abschließen = to sign a contract).", cat:"irregolare"},
  {inf:"abwaschen", pres:"wäscht ab", pra:"wusch ab", perf:"hat abgewaschen", it:"lavare i piatti", en:"to wash up", ex:[["Nach dem Essen wasche ich ab.","Dopo mangiato lavo i piatti."]], enex:[["Nach dem Essen wasche ich ab.","After the meal I do the washing-up."]], note:"Separabile. Sinonimo colloquiale: Geschirr spülen.", enNote:"Separable. Colloquial synonym: Geschirr spülen.", cat:"irregolare"},
  {inf:"an sein", pres:"ist an", pra:"war an", perf:"ist an gewesen", it:"essere acceso", en:"to be on", ex:[["Das Licht ist noch an.","La luce è ancora accesa."]], enex:[["Das Licht ist noch an.","The light is still on."]], note:"Colloquiale, per apparecchi. Il contrario è aus sein.", enNote:"Colloquial, used for devices. The opposite is aus sein.", cat:"irregolare"},
  {inf:"anbieten", pres:"bietet an", pra:"bot an", perf:"hat angeboten", it:"offrire", en:"to offer", ex:[["Darf ich Ihnen einen Kaffee anbieten?","Posso offrirle un caffè?"]], enex:[["Darf ich Ihnen einen Kaffee anbieten?","May I offer you a coffee?"]], note:"Separabile. jdm etw Akk anbieten: la persona in dativo, prima della cosa. Se la cosa è un pronome va davanti: Sie bietet es den Expats an.", enNote:"Separable. jdm etw Akk anbieten: the person takes the dative and comes before the thing. If the thing is a pronoun it goes first: Sie bietet es den Expats an.", cat:"irregolare"},
  {inf:"angeben", pres:"gibt an", pra:"gab an", perf:"hat angegeben", it:"indicare / vantarsi", en:"to state / to show off", ex:[["Bitte geben Sie Ihre Adresse an.","Indichi il suo indirizzo, per favore."]], enex:[["Bitte geben Sie Ihre Adresse an.","Please state your address."]], note:"Separabile. Nei moduli = indicare un dato; nel parlato = vantarsi.", enNote:"Separable. On forms = to state a detail; colloquially = to brag.", cat:"irregolare"},
  {inf:"annehmen", pres:"nimmt an", pra:"nahm an", perf:"hat angenommen", it:"accettare / supporre", en:"to accept / to assume", ex:[["Ich nehme die Einladung gern an.","Accetto volentieri l'invito."]], enex:[["Ich nehme die Einladung gern an.","I'm happy to accept the invitation."]], note:"Separabile. Due sensi: accettare qualcosa, e dare per scontato (Ich nehme an, dass…).", enNote:"Separable. Two senses: to accept something, and to assume (Ich nehme an, dass…).", cat:"irregolare"},
  {inf:"ansehen", pres:"sieht an", pra:"sah an", perf:"hat angesehen", it:"guardare", en:"to look at", ex:[["Wir haben uns die Bilder angesehen.","Abbiamo guardato le foto."]], enex:[["Wir haben uns die Bilder angesehen.","We looked at the pictures."]], note:"Separabile. Spesso con dativo riflessivo: sich Dat etw ansehen = guardarsi qualcosa con calma.", enNote:"Separable. Often with a dative reflexive: sich Dat etw ansehen = to have a proper look at something.", cat:"irregolare"},
  {inf:"ansprechen", pres:"spricht an", pra:"sprach an", perf:"hat angesprochen", it:"rivolgere la parola / affrontare un tema", en:"to address / to bring up", ex:[["Er hat mich auf der Straße angesprochen.","Mi ha rivolto la parola per strada."]], enex:[["Er hat mich auf der Straße angesprochen.","He spoke to me in the street."]], note:"Separabile. jdn ansprechen = rivolgersi a qualcuno · ein Thema ansprechen = tirare fuori un argomento.", enNote:"Separable. jdn ansprechen = to approach someone · ein Thema ansprechen = to raise a topic.", cat:"irregolare"},
  {inf:"anwenden", pres:"wendet an", pra:"wandte an", perf:"hat angewandt", it:"applicare / usare", en:"to apply / to use", ex:[["Diese Regel wendet man selten an.","Questa regola si applica di rado."]], enex:[["Diese Regel wendet man selten an.","This rule is rarely applied."]], note:"Separabile. Ammesse anche le forme deboli: wendete an, hat angewendet.", enNote:"Separable. Weak forms are also allowed: wendete an, hat angewendet.", cat:"irregolare"},
  {inf:"anziehen", pres:"zieht an", pra:"zog an", perf:"hat angezogen", it:"indossare / vestire", en:"to put on", ex:[["Zieh die Jacke an, es ist kalt.","Mettiti la giacca, fa freddo."]], enex:[["Zieh die Jacke an, es ist kalt.","Put your jacket on, it's cold."]], note:"Separabile. Riflessivo: sich anziehen = vestirsi. Il contrario è ausziehen.", enNote:"Separable. Reflexive: sich anziehen = to get dressed. The opposite is ausziehen.", cat:"irregolare"},
  {inf:"aufgeben", pres:"gibt auf", pra:"gab auf", perf:"hat aufgegeben", it:"rinunciare / spedire", en:"to give up / to post", ex:[["Gib nicht so schnell auf!","Non arrenderti così in fretta!"]], enex:[["Gib nicht so schnell auf!","Don't give up so quickly!"]], note:"Separabile. Anche: einen Brief aufgeben = imbucare una lettera · Hausaufgaben aufgeben = assegnare i compiti.", enNote:"Separable. Also: einen Brief aufgeben = to post a letter · Hausaufgaben aufgeben = to set homework.", cat:"irregolare"},
  {inf:"aufladen", pres:"lädt auf", pra:"lud auf", perf:"hat aufgeladen", it:"caricare", en:"to charge / to load", ex:[["Ich muss mein Handy aufladen.","Devo caricare il cellulare."]], enex:[["Ich muss mein Handy aufladen.","I need to charge my phone."]], note:"Separabile. Vale per batterie, ricariche e carichi da trasportare.", enNote:"Separable. Used for batteries, top-ups and physical loads.", cat:"irregolare"},
  {inf:"aufschreiben", pres:"schreibt auf", pra:"schrieb auf", perf:"hat aufgeschrieben", it:"annotare", en:"to write down", ex:[["Schreib dir die Nummer auf!","Annotati il numero!"]], enex:[["Schreib dir die Nummer auf!","Write the number down!"]], note:"Separabile. Spesso con dativo riflessivo: sich Dat etw aufschreiben.", enNote:"Separable. Often with a dative reflexive: sich Dat etw aufschreiben.", cat:"irregolare"},
  {inf:"auf sein", pres:"ist auf", pra:"war auf", perf:"ist auf gewesen", it:"essere aperto / essere alzato", en:"to be open / to be up", ex:[["Das Fenster ist auf.","La finestra è aperta."]], enex:[["Das Fenster ist auf.","The window is open."]], note:"Colloquiale. Anche: Ich bin schon seit sechs auf = sono in piedi dalle sei.", enNote:"Colloquial. Also: Ich bin schon seit sechs auf = I've been up since six.", cat:"irregolare"},
  {inf:"auftreten", pres:"tritt auf", pra:"trat auf", perf:"ist aufgetreten", it:"esibirsi / presentarsi", en:"to perform / to appear", ex:[["Die Band tritt heute Abend auf.","La band si esibisce stasera."]], enex:[["Die Band tritt heute Abend auf.","The band is performing tonight."]], note:"Separabile, con sein. Anche: comportarsi (selbstbewusst auftreten) e presentarsi di un problema (Probleme treten auf).", enNote:"Separable, with sein. Also: to come across (selbstbewusst auftreten) and for problems arising (Probleme treten auf).", cat:"irregolare"},
  {inf:"aufwachsen", pres:"wächst auf", pra:"wuchs auf", perf:"ist aufgewachsen", it:"crescere (diventare grande)", en:"to grow up", ex:[["Sie ist in Berlin aufgewachsen.","È cresciuta a Berlino."]], enex:[["Sie ist in Berlin aufgewachsen.","She grew up in Berlin."]], note:"Separabile, con sein. Riguarda le persone; per le piante si usa wachsen.", enNote:"Separable, with sein. Used for people; for plants use wachsen.", cat:"irregolare"},
  {inf:"aus sein", pres:"ist aus", pra:"war aus", perf:"ist aus gewesen", it:"essere spento / essere finito", en:"to be off / to be over", ex:[["Der Film ist schon aus.","Il film è già finito."]], enex:[["Der Film ist schon aus.","The film is already over."]], note:"Colloquiale. Per apparecchi = spento; per eventi = terminato.", enNote:"Colloquial. For devices = switched off; for events = finished.", cat:"irregolare"},
  {inf:"ausgeben", pres:"gibt aus", pra:"gab aus", perf:"hat ausgegeben", it:"spendere", en:"to spend (money)", ex:[["Ich habe zu viel Geld ausgegeben.","Ho speso troppi soldi."]], enex:[["Ich habe zu viel Geld ausgegeben.","I spent too much money."]], note:"Separabile. Solo per il DENARO: per il tempo si usa verbringen.", enNote:"Separable. Only for MONEY: for time use verbringen.", cat:"irregolare"},
  {inf:"ausladen", pres:"lädt aus", pra:"lud aus", perf:"hat ausgeladen", it:"scaricare / disdire un invito", en:"to unload / to uninvite", ex:[["Wir laden das Auto aus.","Scarichiamo la macchina."]], enex:[["Wir laden das Auto aus.","We're unloading the car."]], note:"Separabile. Il contrario di einladen in tutti e due i sensi: caricare e invitare.", enNote:"Separable. The opposite of einladen in both senses: loading and inviting.", cat:"irregolare"},
  {inf:"ausleihen", pres:"leiht aus", pra:"lieh aus", perf:"hat ausgeliehen", it:"prendere in prestito", en:"to borrow", ex:[["Ich habe mir ein Buch aus der Bibliothek ausgeliehen.","Ho preso in prestito un libro dalla biblioteca."]], enex:[["Ich habe mir ein Buch aus der Bibliothek ausgeliehen.","I borrowed a book from the library."]], note:"Separabile. sich Dat etw ausleihen = prendere in prestito · jdm etw ausleihen = prestare a qualcuno.", enNote:"Separable. sich Dat etw ausleihen = to borrow · jdm etw ausleihen = to lend to someone.", cat:"irregolare"},
  {inf:"aussehen", pres:"sieht aus", pra:"sah aus", perf:"hat ausgesehen", it:"avere l'aria / sembrare", en:"to look (like)", ex:[["Du siehst müde aus.","Hai l'aria stanca."]], enex:[["Du siehst müde aus.","You look tired."]], note:"Separabile. Riguarda l'aspetto visibile; per un'impressione generale si usa scheinen o wirken.", enNote:"Separable. About visible appearance; for a general impression use scheinen or wirken.", cat:"irregolare"},
  {inf:"aussprechen", pres:"spricht aus", pra:"sprach aus", perf:"hat ausgesprochen", it:"pronunciare", en:"to pronounce", ex:[["Wie spricht man dieses Wort aus?","Come si pronuncia questa parola?"]], enex:[["Wie spricht man dieses Wort aus?","How do you pronounce this word?"]], note:"Separabile. Il sostantivo è die Aussprache = la pronuncia.", enNote:"Separable. The noun is die Aussprache = pronunciation.", cat:"irregolare"},
  {inf:"aussteigen", pres:"steigt aus", pra:"stieg aus", perf:"ist ausgestiegen", it:"scendere (da un mezzo)", en:"to get off", ex:[["Wir steigen an der nächsten Haltestelle aus.","Scendiamo alla prossima fermata."]], enex:[["Wir steigen an der nächsten Haltestelle aus.","We're getting off at the next stop."]], note:"Separabile, con sein. Trio da imparare insieme: einsteigen · umsteigen · aussteigen.", enNote:"Separable, with sein. Learn the trio together: einsteigen · umsteigen · aussteigen.", cat:"irregolare"},
  {inf:"austragen", pres:"trägt aus", pra:"trug aus", perf:"hat ausgetragen", it:"consegnare (a domicilio)", en:"to deliver", ex:[["Er trägt jeden Morgen Zeitungen aus.","Ogni mattina consegna i giornali."]], enex:[["Er trägt jeden Morgen Zeitungen aus.","He delivers newspapers every morning."]], note:"Separabile. Anche: einen Wettkampf austragen = disputare una gara.", enNote:"Separable. Also: einen Wettkampf austragen = to hold a competition.", cat:"irregolare"},
  {inf:"ausziehen", pres:"zieht aus", pra:"zog aus", perf:"hat ausgezogen", it:"togliersi (un vestito) / traslocare", en:"to take off / to move out", ex:[["Zieh die nassen Schuhe aus!","Togliti le scarpe bagnate!"],["Sie ist letzte Woche ausgezogen.","Si è trasferita la settimana scorsa."]], enex:[["Zieh die nassen Schuhe aus!","Take off your wet shoes!"],["Sie ist letzte Woche ausgezogen.","She moved out last week."]], note:"Separabile con DUE ausiliari: hat ausgezogen per i vestiti, ist ausgezogen per il trasloco.", enNote:"Separable with TWO auxiliaries: hat ausgezogen for clothes, ist ausgezogen for moving house.", cat:"irregolare"},
  {inf:"behalten", pres:"behält", pra:"behielt", perf:"hat behalten", it:"tenere / conservare", en:"to keep", ex:[["Du kannst das Buch behalten.","Puoi tenere il libro."]], enex:[["Du kannst das Buch behalten.","You can keep the book."]], note:"Inseparabile: niente ge- al Partizip. Anche: etw im Kopf behalten = ricordarsi qualcosa.", enNote:"Inseparable: no ge- in the past participle. Also: etw im Kopf behalten = to remember something.", cat:"irregolare"},
  {inf:"bekommen", pres:"bekommt", pra:"bekam", perf:"hat bekommen", it:"ricevere / ottenere", en:"to get / to receive", ex:[["Ich habe deinen Brief bekommen.","Ho ricevuto la tua lettera."]], enex:[["Ich habe deinen Brief bekommen.","I got your letter."]], note:"Falso amico: NON significa diventare (= werden). Inseparabile, niente ge-.", enNote:"False friend: it does NOT mean to become (= werden). Inseparable, no ge-.", cat:"irregolare"},
  {inf:"beschließen", pres:"beschließt", pra:"beschloss", perf:"hat beschlossen", it:"decidere / deliberare", en:"to decide / to resolve", ex:[["Sie haben beschlossen, das Haus zu verkaufen.","Hanno deciso di vendere la casa."]], enex:[["Sie haben beschlossen, das Haus zu verkaufen.","They decided to sell the house."]], note:"Inseparabile. Decisione formale o definitiva; per la scelta fra alternative si usa sich entscheiden für.", enNote:"Inseparable. A formal or final decision; for choosing between options use sich entscheiden für.", cat:"irregolare"},
  {inf:"besprechen", pres:"bespricht", pra:"besprach", perf:"hat besprochen", it:"discutere insieme", en:"to discuss", ex:[["Wir besprechen das Problem morgen.","Discutiamo il problema domani."]], enex:[["Wir besprechen das Problem morgen.","We'll discuss the problem tomorrow."]], note:"Inseparabile. etw Akk mit jdm besprechen: qui l'argomento è diretto, senza preposizione.", enNote:"Inseparable. etw Akk mit jdm besprechen: here the topic is a direct object, with no preposition.", cat:"irregolare"},
  {inf:"beziehen", pres:"bezieht", pra:"bezog", perf:"hat bezogen", it:"riferirsi / rifare (il letto)", en:"to refer / to change (bedding)", ex:[["Der Text bezieht sich auf das Thema Umwelt.","Il testo si riferisce al tema ambiente."]], enex:[["Der Text bezieht sich auf das Thema Umwelt.","The text refers to the topic of the environment."]], note:"Inseparabile. sich beziehen auf + Akk = riferirsi a. Anche: das Bett beziehen = mettere le lenzuola pulite.", enNote:"Inseparable. sich beziehen auf + Akk = to refer to. Also: das Bett beziehen = to put clean sheets on.", cat:"irregolare"},
  {inf:"bieten", pres:"bietet", pra:"bot", perf:"hat geboten", it:"offrire / presentare", en:"to offer", ex:[["Die Stadt bietet viele Möglichkeiten.","La città offre molte possibilità."]], enex:[["Die Stadt bietet viele Möglichkeiten.","The city offers many opportunities."]], note:"Più astratto di anbieten: si usa per possibilità, vantaggi, spettacoli.", enNote:"More abstract than anbieten: used for opportunities, advantages, sights.", cat:"irregolare"},
  {inf:"braten", pres:"brät", pra:"briet", perf:"hat gebraten", it:"arrostire / friggere in padella", en:"to fry / to roast", ex:[["Ich brate das Fleisch in der Pfanne.","Cucino la carne in padella."]], enex:[["Ich brate das Fleisch in der Pfanne.","I'm frying the meat in the pan."]], note:"In padella o al forno con grasso. Confronta: backen (in forno, dolci e pane) · kochen (bollire).", enNote:"In a pan or in the oven with fat. Compare: backen (baking) · kochen (boiling).", cat:"irregolare"},
  {inf:"brechen", pres:"bricht", pra:"brach", perf:"hat gebrochen", it:"rompere / spezzare", en:"to break", ex:[["Er hat sich den Arm gebrochen.","Si è rotto un braccio."]], enex:[["Er hat sich den Arm gebrochen.","He broke his arm."]], note:"Con haben se c'è un oggetto; con sein se qualcosa si rompe da solo (Das Eis ist gebrochen).", enNote:"With haben when there is an object; with sein when something breaks by itself (Das Eis ist gebrochen).", cat:"irregolare"},
  {inf:"brennen", pres:"brennt", pra:"brannte", perf:"hat gebrannt", it:"bruciare / ardere", en:"to burn", ex:[["Im Kamin brennt ein Feuer.","Nel camino arde un fuoco."]], enex:[["Im Kamin brennt ein Feuer.","A fire is burning in the fireplace."]], note:"Verbo misto: Präteritum debole in -te ma vocale cambiata. Anche: Das Licht brennt = la luce è accesa.", enNote:"Mixed verb: weak -te Präteritum but a changed vowel. Also: Das Licht brennt = the light is on.", cat:"irregolare"},
  {inf:"dalassen", pres:"lässt da", pra:"ließ da", perf:"hat dagelassen", it:"lasciare lì", en:"to leave (something) there", ex:[["Lass die Tasche einfach da.","Lascia pure lì la borsa."]], enex:[["Lass die Tasche einfach da.","Just leave the bag there."]], note:"Separabile, colloquiale. Della famiglia di lassen: dalassen · hierlassen · zurücklassen.", enNote:"Separable, colloquial. From the lassen family: dalassen · hierlassen · zurücklassen.", cat:"irregolare"},
  {inf:"dasitzen", pres:"sitzt da", pra:"saß da", perf:"hat dagesessen", it:"starsene lì seduto", en:"to sit there", ex:[["Er saß den ganzen Tag da und sagte nichts.","Se ne stava lì seduto tutto il giorno senza dire niente."]], enex:[["Er saß den ganzen Tag da und sagte nichts.","He sat there all day saying nothing."]], note:"Separabile. Nel sud della Germania, in Austria e in Svizzera: ist dagesessen.", enNote:"Separable. In southern Germany, Austria and Switzerland: ist dagesessen.", cat:"irregolare"},
  {inf:"dazuschreiben", pres:"schreibt dazu", pra:"schrieb dazu", perf:"hat dazugeschrieben", it:"aggiungere per iscritto", en:"to add in writing", ex:[["Schreib bitte dein Geburtsdatum dazu.","Aggiungi per favore la tua data di nascita."]], enex:[["Schreib bitte dein Geburtsdatum dazu.","Please add your date of birth."]], note:"Separabile. dazu- = in aggiunta a qualcosa che c'è già.", enNote:"Separable. dazu- = in addition to something already there.", cat:"irregolare"},
  {inf:"durchstreichen", pres:"streicht durch", pra:"strich durch", perf:"hat durchgestrichen", it:"cancellare con un tratto", en:"to cross out", ex:[["Streich das falsche Wort durch.","Cancella la parola sbagliata."]], enex:[["Streich das falsche Wort durch.","Cross out the wrong word."]], note:"Separabile. Confronta unterstreichen (inseparabile) = sottolineare.", enNote:"Separable. Compare unterstreichen (inseparable) = to underline.", cat:"irregolare"},
  {inf:"einbrechen", pres:"bricht ein", pra:"brach ein", perf:"ist eingebrochen", it:"introdursi con effrazione", en:"to break in", ex:[["Bei uns ist eingebrochen worden.","Da noi c'è stato un furto con scasso."]], enex:[["Bei uns ist eingebrochen worden.","Our place was broken into."]], note:"Separabile, con sein. in + Akk einbrechen. Il sostantivo è der Einbruch.", enNote:"Separable, with sein. in + Akk einbrechen. The noun is der Einbruch.", cat:"irregolare"},
  {inf:"eingeben", pres:"gibt ein", pra:"gab ein", perf:"hat eingegeben", it:"inserire (dati)", en:"to enter (data)", ex:[["Geben Sie bitte Ihr Passwort ein.","Inserisca la sua password."]], enex:[["Geben Sie bitte Ihr Passwort ein.","Please enter your password."]], note:"Separabile. Termine informatico: dati, PIN, password.", enNote:"Separable. A computing term: data, PIN, password.", cat:"irregolare"},
  {inf:"einhalten", pres:"hält ein", pra:"hielt ein", perf:"hat eingehalten", it:"rispettare (una regola, un termine)", en:"to keep to / to comply with", ex:[["Wir müssen den Termin einhalten.","Dobbiamo rispettare la scadenza."]], enex:[["Wir müssen den Termin einhalten.","We have to keep to the deadline."]], note:"Separabile. Si usa con Regeln, Termine, Versprechen.", enNote:"Separable. Used with Regeln, Termine, Versprechen.", cat:"irregolare"},
  {inf:"einnehmen", pres:"nimmt ein", pra:"nahm ein", perf:"hat eingenommen", it:"assumere (un medicinale)", en:"to take (medicine)", ex:[["Nehmen Sie die Tabletten dreimal täglich ein.","Prenda le compresse tre volte al giorno."]], enex:[["Nehmen Sie die Tabletten dreimal täglich ein.","Take the tablets three times a day."]], note:"Separabile, linguaggio medico. Anche: einen Platz einnehmen = occupare un posto.", enNote:"Separable, medical register. Also: einen Platz einnehmen = to occupy a place.", cat:"irregolare"},
  {inf:"einschlagen", pres:"schlägt ein", pra:"schlug ein", perf:"hat eingeschlagen", it:"conficcare / imboccare", en:"to knock in / to take (a road)", ex:[["Er hat einen Nagel in die Wand eingeschlagen.","Ha piantato un chiodo nel muro."]], enex:[["Er hat einen Nagel in die Wand eingeschlagen.","He knocked a nail into the wall."]], note:"Separabile. Anche: einen Weg einschlagen = imboccare una strada, anche in senso figurato.", enNote:"Separable. Also: einen Weg einschlagen = to take a path, including figuratively.", cat:"irregolare"},
  {inf:"einsteigen", pres:"steigt ein", pra:"stieg ein", perf:"ist eingestiegen", it:"salire (su un mezzo)", en:"to get on / to get in", ex:[["Bitte einsteigen und die Türen schließen!","Salire e chiudere le porte, prego!"]], enex:[["Bitte einsteigen und die Türen schließen!","Please board and close the doors!"]], note:"Separabile, con sein. in + Akk einsteigen.", enNote:"Separable, with sein. in + Akk einsteigen.", cat:"irregolare"},
  {inf:"eintragen", pres:"trägt ein", pra:"trug ein", perf:"hat eingetragen", it:"iscrivere / annotare", en:"to enter / to register", ex:[["Trag deinen Namen in die Liste ein.","Scrivi il tuo nome nella lista."]], enex:[["Trag deinen Namen in die Liste ein.","Enter your name on the list."]], note:"Separabile. Riflessivo: sich eintragen = iscriversi.", enNote:"Separable. Reflexive: sich eintragen = to sign up.", cat:"irregolare"},
  {inf:"einziehen", pres:"zieht ein", pra:"zog ein", perf:"ist eingezogen", it:"trasferirsi (in una casa)", en:"to move in", ex:[["Wir ziehen nächsten Monat in die neue Wohnung ein.","Il mese prossimo ci trasferiamo nella casa nuova."]], enex:[["Wir ziehen nächsten Monat in die neue Wohnung ein.","We're moving into the new flat next month."]], note:"Separabile, con sein. Terzetto del trasloco: einziehen · umziehen · ausziehen.", enNote:"Separable, with sein. The moving trio: einziehen · umziehen · ausziehen.", cat:"irregolare"},
  {inf:"empfehlen", pres:"empfiehlt", pra:"empfahl", perf:"hat empfohlen", it:"consigliare / raccomandare", en:"to recommend", ex:[["Können Sie mir ein gutes Restaurant empfehlen?","Può consigliarmi un buon ristorante?"]], enex:[["Können Sie mir ein gutes Restaurant empfehlen?","Can you recommend me a good restaurant?"]], note:"Inseparabile. jdm etw Akk empfehlen: la persona in dativo. Nota il cambio di vocale e → ie → a → o.", enNote:"Inseparable. jdm etw Akk empfehlen: the person takes the dative. Note the vowel change e → ie → a → o.", cat:"irregolare"},
  {inf:"entfallen", pres:"entfällt", pra:"entfiel", perf:"ist entfallen", it:"essere annullato / sfuggire", en:"to be cancelled / to slip one's mind", ex:[["Der Unterricht entfällt heute.","Oggi la lezione è annullata."]], enex:[["Der Unterricht entfällt heute.","Today's lesson is cancelled."]], note:"Inseparabile, con sein. Formale. Anche: Der Name ist mir entfallen = il nome mi è sfuggito.", enNote:"Inseparable, with sein. Formal. Also: Der Name ist mir entfallen = the name escaped me.", cat:"irregolare"},
  {inf:"entlanglaufen", pres:"läuft entlang", pra:"lief entlang", perf:"ist entlanggelaufen", it:"camminare lungo", en:"to walk along", ex:[["Wir sind am Fluss entlanggelaufen.","Abbiamo camminato lungo il fiume."]], enex:[["Wir sind am Fluss entlanggelaufen.","We walked along the river."]], note:"Separabile, con sein. entlang segue il nome: den Fluss entlang, am Fluss entlang.", enNote:"Separable, with sein. entlang follows the noun: den Fluss entlang, am Fluss entlang.", cat:"irregolare"},
  {inf:"entlassen", pres:"entlässt", pra:"entließ", perf:"hat entlassen", it:"licenziare / dimettere", en:"to dismiss / to discharge", ex:[["Die Firma hat zehn Mitarbeiter entlassen.","L'azienda ha licenziato dieci dipendenti."]], enex:[["Die Firma hat zehn Mitarbeiter entlassen.","The company laid off ten employees."]], note:"Inseparabile. Anche dall'ospedale: aus dem Krankenhaus entlassen werden.", enNote:"Inseparable. Also from hospital: aus dem Krankenhaus entlassen werden.", cat:"irregolare"},
  {inf:"entstehen", pres:"entsteht", pra:"entstand", perf:"ist entstanden", it:"nascere / formarsi", en:"to arise / to come into being", ex:[["So sind viele Missverständnisse entstanden.","Così sono nati molti malintesi."]], enex:[["So sind viele Missverständnisse entstanden.","That's how many misunderstandings arose."]], note:"Inseparabile, con sein. Non ha oggetto: qualcosa nasce da sé.", enNote:"Inseparable, with sein. No object: something comes about by itself.", cat:"irregolare"},
  {inf:"erfinden", pres:"erfindet", pra:"erfand", perf:"hat erfunden", it:"inventare", en:"to invent", ex:[["Gutenberg hat den Buchdruck erfunden.","Gutenberg ha inventato la stampa."]], enex:[["Gutenberg hat den Buchdruck erfunden.","Gutenberg invented printing."]], note:"Inseparabile. Confronta entdecken = scoprire qualcosa che già esisteva.", enNote:"Inseparable. Compare entdecken = to discover something that already existed.", cat:"irregolare"},
  {inf:"ergeben", pres:"ergibt", pra:"ergab", perf:"hat ergeben", it:"dare come risultato", en:"to result in", ex:[["Die Untersuchung hat nichts ergeben.","L'indagine non ha dato alcun risultato."]], enex:[["Die Untersuchung hat nichts ergeben.","The investigation produced nothing."]], note:"Inseparabile. Riflessivo: sich ergeben = risultare, oppure arrendersi.", enNote:"Inseparable. Reflexive: sich ergeben = to turn out, or to surrender.", cat:"irregolare"},
  {inf:"erkennen", pres:"erkennt", pra:"erkannte", perf:"hat erkannt", it:"riconoscere", en:"to recognise", ex:[["Ich habe dich sofort erkannt.","Ti ho riconosciuto subito."]], enex:[["Ich habe dich sofort erkannt.","I recognised you right away."]], note:"Verbo misto e inseparabile. jdn an etw Dat erkennen = riconoscere qualcuno da qualcosa.", enNote:"Mixed and inseparable. jdn an etw Dat erkennen = to recognise someone by something.", cat:"irregolare"},
  {inf:"erziehen", pres:"erzieht", pra:"erzog", perf:"hat erzogen", it:"educare", en:"to bring up / to educate", ex:[["Sie erziehen ihre Kinder sehr streng.","Educano i figli in modo molto severo."]], enex:[["Sie erziehen ihre Kinder sehr streng.","They bring up their children very strictly."]], note:"Inseparabile. Riguarda l'educazione familiare; per la scuola si usa unterrichten.", enNote:"Inseparable. About upbringing; for school teaching use unterrichten.", cat:"irregolare"},
  {inf:"fernsehen", pres:"sieht fern", pra:"sah fern", perf:"hat ferngesehen", it:"guardare la televisione", en:"to watch television", ex:[["Abends sehe ich eine Stunde fern.","La sera guardo la tv per un'ora."]], enex:[["Abends sehe ich eine Stunde fern.","In the evening I watch TV for an hour."]], note:"Separabile e senza oggetto: si dice fernsehen, non den Fernseher sehen.", enNote:"Separable and object-free: say fernsehen, not den Fernseher sehen.", cat:"irregolare"},
  {inf:"festhalten", pres:"hält fest", pra:"hielt fest", perf:"hat festgehalten", it:"tenere stretto / mettere per iscritto", en:"to hold on to / to record", ex:[["Halt dich gut fest!","Tieniti forte!"]], enex:[["Halt dich gut fest!","Hold on tight!"]], note:"Separabile. Riflessivo: sich festhalten an + Dat. Anche: etw schriftlich festhalten = mettere a verbale.", enNote:"Separable. Reflexive: sich festhalten an + Dat. Also: etw schriftlich festhalten = to put on record.", cat:"irregolare"},
  {inf:"festnehmen", pres:"nimmt fest", pra:"nahm fest", perf:"hat festgenommen", it:"arrestare", en:"to arrest", ex:[["Die Polizei hat den Täter festgenommen.","La polizia ha arrestato il colpevole."]], enex:[["Die Polizei hat den Täter festgenommen.","The police arrested the culprit."]], note:"Separabile, linguaggio giuridico. Il sostantivo è die Festnahme.", enNote:"Separable, legal register. The noun is die Festnahme.", cat:"irregolare"},
  {inf:"fliehen", pres:"flieht", pra:"floh", perf:"ist geflohen", it:"fuggire", en:"to flee", ex:[["Sie sind vor dem Krieg geflohen.","Sono fuggiti dalla guerra."]], enex:[["Sie sind vor dem Krieg geflohen.","They fled from the war."]], note:"Con sein. fliehen vor + Dat = fuggire da qualcosa. Non confondere con fliegen (volare).", enNote:"With sein. fliehen vor + Dat = to flee from something. Don't confuse with fliegen (to fly).", cat:"irregolare"},
  {inf:"freihaben", pres:"hat frei", pra:"hatte frei", perf:"hat freigehabt", it:"avere un giorno libero", en:"to have time off", ex:[["Am Freitag habe ich frei.","Venerdì sono libero."]], enex:[["Am Freitag habe ich frei.","I have Friday off."]], note:"Separabile, colloquiale. Si riferisce al lavoro o alla scuola.", enNote:"Separable, colloquial. Refers to work or school.", cat:"irregolare"},
  {inf:"frieren", pres:"friert", pra:"fror", perf:"hat gefroren", it:"avere freddo / gelare", en:"to be cold / to freeze", ex:[["Ich friere, mach bitte das Fenster zu.","Ho freddo, chiudi la finestra per favore."]], enex:[["Ich friere, mach bitte das Fenster zu.","I'm cold, please close the window."]], note:"Anche impersonale: Es friert = gela. Con sein quando l'acqua ghiaccia: Der See ist gefroren.", enNote:"Also impersonal: Es friert = it's freezing. With sein when water freezes: Der See ist gefroren.", cat:"irregolare"},
  {inf:"gelingen", pres:"gelingt", pra:"gelang", perf:"ist gelungen", it:"riuscire", en:"to succeed", ex:[["Der Kuchen ist mir gut gelungen.","La torta mi è venuta bene."]], enex:[["Der Kuchen ist mir gut gelungen.","The cake turned out well."]], note:"Con sein. La persona va in DATIVO: es gelingt mir. Il contrario è misslingen.", enNote:"With sein. The person takes the DATIVE: es gelingt mir. The opposite is misslingen.", cat:"irregolare"},
  {inf:"gelten", pres:"gilt", pra:"galt", perf:"hat gegolten", it:"valere / essere valido", en:"to be valid / to apply", ex:[["Die Fahrkarte gilt zwei Stunden.","Il biglietto vale due ore."]], enex:[["Die Fahrkarte gilt zwei Stunden.","The ticket is valid for two hours."]], note:"Anche: gelten als = essere considerato — Er gilt als sehr zuverlässig.", enNote:"Also: gelten als = to be regarded as — Er gilt als sehr zuverlässig.", cat:"irregolare"},
  {inf:"genießen", pres:"genießt", pra:"genoss", perf:"hat genossen", it:"godersi", en:"to enjoy", ex:[["Wir haben den Abend sehr genossen.","Ci siamo goduti molto la serata."]], enex:[["Wir haben den Abend sehr genossen.","We really enjoyed the evening."]], note:"Regge l'accusativo diretto, senza preposizione. Il sostantivo è der Genuss.", enNote:"Takes a direct accusative, no preposition. The noun is der Genuss.", cat:"irregolare"},
  {inf:"gewinnen", pres:"gewinnt", pra:"gewann", perf:"hat gewonnen", it:"vincere", en:"to win", ex:[["Unsere Mannschaft hat das Spiel gewonnen.","La nostra squadra ha vinto la partita."]], enex:[["Unsere Mannschaft hat das Spiel gewonnen.","Our team won the match."]], note:"Il contrario è verlieren. Anche: Zeit gewinnen = guadagnare tempo.", enNote:"The opposite is verlieren. Also: Zeit gewinnen = to gain time.", cat:"irregolare"},
  {inf:"großschreiben", pres:"schreibt groß", pra:"schrieb groß", perf:"hat großgeschrieben", it:"scrivere con la maiuscola", en:"to capitalise", ex:[["Im Deutschen schreibt man alle Nomen groß.","In tedesco tutti i nomi si scrivono con la maiuscola."]], enex:[["Im Deutschen schreibt man alle Nomen groß.","In German all nouns are capitalised."]], note:"Separabile. Il contrario è kleinschreiben.", enNote:"Separable. The opposite is kleinschreiben.", cat:"irregolare"},
  {inf:"halten", pres:"hält", pra:"hielt", perf:"hat gehalten", it:"tenere / fermarsi", en:"to hold / to stop", ex:[["Der Bus hält hier nicht.","L'autobus qui non ferma."]], enex:[["Der Bus hält hier nicht.","The bus doesn't stop here."]], note:"Anche: halten von + Dat = pensarla su — Was hältst du davon? · sich an etw Akk halten = attenersi a.", enNote:"Also: halten von + Dat = to think of — Was hältst du davon? · sich an etw Akk halten = to stick to.", cat:"irregolare"},
  {inf:"hängen", pres:"hängt", pra:"hing", perf:"hat gehangen", it:"essere appeso", en:"to hang (be hanging)", ex:[["Das Bild hängt an der Wand.","Il quadro è appeso alla parete."]], enex:[["Das Bild hängt an der Wand.","The picture is hanging on the wall."]], note:"Qui è la forma irregolare senza movimento (Wo? + Dativ). Con movimento è REGOLARE: hängen, hängte, hat gehängt (Wohin? + Akkusativ). Nel sud: ist gehangen.", enNote:"This is the irregular, static form (Wo? + dative). With movement it is REGULAR: hängen, hängte, hat gehängt (Wohin? + accusative). In the south: ist gehangen.", cat:"irregolare"},
  {inf:"heben", pres:"hebt", pra:"hob", perf:"hat gehoben", it:"sollevare / alzare", en:"to lift / to raise", ex:[["Er hebt den Koffer auf den Tisch.","Solleva la valigia sul tavolo."]], enex:[["Er hebt den Koffer auf den Tisch.","He lifts the suitcase onto the table."]], note:"Anche: die Hand heben = alzare la mano.", enNote:"Also: die Hand heben = to raise one's hand.", cat:"irregolare"},
  {inf:"herausfinden", pres:"findet heraus", pra:"fand heraus", perf:"hat herausgefunden", it:"scoprire / venire a sapere", en:"to find out", ex:[["Ich habe herausgefunden, wo er wohnt.","Ho scoperto dove abita."]], enex:[["Ich habe herausgefunden, wo er wohnt.","I found out where he lives."]], note:"Separabile. Nel parlato spesso rausfinden.", enNote:"Separable. Colloquially often rausfinden.", cat:"irregolare"},
  {inf:"hereinkommen", pres:"kommt herein", pra:"kam herein", perf:"ist hereingekommen", it:"entrare", en:"to come in", ex:[["Kommen Sie bitte herein!","Entri, prego!"]], enex:[["Kommen Sie bitte herein!","Please come in!"]], note:"Separabile, con sein. her- = verso chi parla. Nel parlato: reinkommen.", enNote:"Separable, with sein. her- = towards the speaker. Colloquially: reinkommen.", cat:"irregolare"},
  {inf:"hierbleiben", pres:"bleibt hier", pra:"blieb hier", perf:"ist hiergeblieben", it:"restare qui", en:"to stay here", ex:[["Bleib bitte hier und warte auf mich.","Resta qui e aspettami."]], enex:[["Bleib bitte hier und warte auf mich.","Please stay here and wait for me."]], note:"Separabile, con sein come tutti i composti di bleiben.", enNote:"Separable, with sein like all bleiben compounds.", cat:"irregolare"},
  {inf:"hierlassen", pres:"lässt hier", pra:"ließ hier", perf:"hat hiergelassen", it:"lasciare qui", en:"to leave here", ex:[["Lass deinen Mantel hier.","Lascia qui il cappotto."]], enex:[["Lass deinen Mantel hier.","Leave your coat here."]], note:"Separabile. Attenzione: lassen ha il Perfekt con haben, bleiben con sein.", enNote:"Separable. Note: lassen forms the Perfekt with haben, bleiben with sein.", cat:"irregolare"},
  {inf:"hinterlassen", pres:"hinterlässt", pra:"hinterließ", perf:"hat hinterlassen", it:"lasciare (dietro di sé)", en:"to leave behind", ex:[["Er hat eine Nachricht hinterlassen.","Ha lasciato un messaggio."]], enex:[["Er hat eine Nachricht hinterlassen.","He left a message."]], note:"Inseparabile: niente ge-. Anche in senso di eredità o di impressione lasciata.", enNote:"Inseparable: no ge-. Also for inheritance or the impression one leaves.", cat:"irregolare"},
  {inf:"kaputtgehen", pres:"geht kaputt", pra:"ging kaputt", perf:"ist kaputtgegangen", it:"rompersi / guastarsi", en:"to break down", ex:[["Meine Waschmaschine ist kaputtgegangen.","La mia lavatrice si è rotta."]], enex:[["Meine Waschmaschine ist kaputtgegangen.","My washing machine broke down."]], note:"Separabile, con sein. Colloquiale ma molto usato.", enNote:"Separable, with sein. Colloquial but very common.", cat:"irregolare"},
  {inf:"krankschreiben", pres:"schreibt krank", pra:"schrieb krank", perf:"hat krankgeschrieben", it:"mettere in malattia", en:"to sign off sick", ex:[["Der Arzt hat mich für eine Woche krankgeschrieben.","Il medico mi ha messo in malattia per una settimana."]], enex:[["Der Arzt hat mich für eine Woche krankgeschrieben.","The doctor signed me off sick for a week."]], note:"Separabile. Il certificato è die Krankschreibung.", enNote:"Separable. The certificate is die Krankschreibung.", cat:"irregolare"},
  {inf:"laden", pres:"lädt", pra:"lud", perf:"hat geladen", it:"caricare", en:"to load", ex:[["Wir laden die Kisten ins Auto.","Carichiamo le casse in macchina."]], enex:[["Wir laden die Kisten ins Auto.","We're loading the boxes into the car."]], note:"Base di aufladen, einladen, ausladen. Occhio: du lädst, er lädt (senza -e-).", enNote:"The base of aufladen, einladen, ausladen. Note: du lädst, er lädt (no -e-).", cat:"irregolare"},
  {inf:"leidtun", pres:"tut leid", pra:"tat leid", perf:"hat leidgetan", it:"dispiacere", en:"to be sorry", ex:[["Es tut mir leid.","Mi dispiace."]], enex:[["Es tut mir leid.","I'm sorry."]], note:"Separabile. La persona va in DATIVO: es tut mir/dir/ihm leid.", enNote:"Separable. The person takes the DATIVE: es tut mir/dir/ihm leid.", cat:"irregolare"},
  {inf:"leihen", pres:"leiht", pra:"lieh", perf:"hat geliehen", it:"prestare", en:"to lend", ex:[["Kannst du mir zehn Euro leihen?","Mi presti dieci euro?"],["Soll ich dir meine Sporttasche leihen? – Kannst du sie mir wirklich leihen?","Ti presto la mia borsa sportiva? – Me la puoi prestare davvero?"]], enex:[["Kannst du mir zehn Euro leihen?","Can you lend me ten euros?"],["Soll ich dir meine Sporttasche leihen? – Kannst du sie mir wirklich leihen?","Shall I lend you my sports bag? – Can you really lend it to me?"]], note:"jdm etw leihen = prestare · sich Dat etw leihen = farsi prestare.", enNote:"jdm etw leihen = to lend · sich Dat etw leihen = to borrow.", cat:"irregolare"},
  {inf:"losgehen", pres:"geht los", pra:"ging los", perf:"ist losgegangen", it:"incamminarsi / cominciare", en:"to set off / to start", ex:[["Wann geht der Film los?","Quando comincia il film?"]], enex:[["Wann geht der Film los?","When does the film start?"]], note:"Separabile, con sein. Colloquiale sia per mettersi in cammino sia per l'inizio di un evento.", enNote:"Separable, with sein. Colloquial for both setting off and an event starting.", cat:"irregolare"},
  {inf:"loslaufen", pres:"läuft los", pra:"lief los", perf:"ist losgelaufen", it:"partire di corsa", en:"to start running / to set off", ex:[["Er ist einfach losgelaufen.","È partito così, di corsa."]], enex:[["Er ist einfach losgelaufen.","He just set off running."]], note:"Separabile, con sein. los- indica l'inizio improvviso di un movimento.", enNote:"Separable, with sein. los- marks the sudden start of a movement.", cat:"irregolare"},
  {inf:"los sein", pres:"ist los", pra:"war los", perf:"ist los gewesen", it:"succedere / esserci movimento", en:"to be going on", ex:[["Was ist denn hier los?","Ma che succede qui?"]], enex:[["Was ist denn hier los?","What's going on here?"]], note:"Colloquiale. Anche: Hier ist viel los = c'è molta animazione.", enNote:"Colloquial. Also: Hier ist viel los = there's a lot going on.", cat:"irregolare"},
  {inf:"lügen", pres:"lügt", pra:"log", perf:"hat gelogen", it:"mentire", en:"to lie (tell lies)", ex:[["Er lügt nie.","Non mente mai."]], enex:[["Er lügt nie.","He never lies."]], note:"Non confondere con liegen (essere disteso), che fa lag, hat gelegen.", enNote:"Don't confuse with liegen (to lie down flat), which is lag, hat gelegen.", cat:"irregolare"},
  {inf:"messen", pres:"misst", pra:"maß", perf:"hat gemessen", it:"misurare", en:"to measure", ex:[["Der Arzt misst den Blutdruck.","Il medico misura la pressione."]], enex:[["Der Arzt misst den Blutdruck.","The doctor measures the blood pressure."]], note:"Cambio di vocale e → i. Il sostantivo è die Messung.", enNote:"Vowel change e → i. The noun is die Messung.", cat:"irregolare"},
  {inf:"mitbringen", pres:"bringt mit", pra:"brachte mit", perf:"hat mitgebracht", it:"portare con sé", en:"to bring along", ex:[["Ich bringe einen Kuchen mit.","Porto una torta."]], enex:[["Ich bringe einen Kuchen mit.","I'll bring a cake."]], note:"Separabile e misto. mitbringen = portare qui · mitnehmen = portare via con sé.", enNote:"Separable and mixed. mitbringen = to bring here · mitnehmen = to take along.", cat:"irregolare"},
  {inf:"mitfahren", pres:"fährt mit", pra:"fuhr mit", perf:"ist mitgefahren", it:"andare insieme (in auto)", en:"to ride along", ex:[["Darf ich mitfahren?","Posso venire con voi in macchina?"]], enex:[["Darf ich mitfahren?","Can I get a lift with you?"]], note:"Separabile, con sein. Die Mitfahrgelegenheit = il passaggio in auto condiviso.", enNote:"Separable, with sein. Die Mitfahrgelegenheit = a shared car ride.", cat:"irregolare"},
  {inf:"mitkommen", pres:"kommt mit", pra:"kam mit", perf:"ist mitgekommen", it:"venire insieme", en:"to come along", ex:[["Kommst du mit ins Kino?","Vieni con me al cinema?"]], enex:[["Kommst du mit ins Kino?","Are you coming along to the cinema?"]], note:"Separabile, con sein. Anche figurato: Kommst du mit? = riesci a seguirmi?", enNote:"Separable, with sein. Also figurative: Kommst du mit? = are you following me?", cat:"irregolare"},
  {inf:"mitlaufen", pres:"läuft mit", pra:"lief mit", perf:"ist mitgelaufen", it:"correre insieme / andare a piedi con", en:"to run along with", ex:[["Sie ist beim Marathon mitgelaufen.","Ha corso anche lei la maratona."]], enex:[["Sie ist beim Marathon mitgelaufen.","She ran in the marathon too."]], note:"Separabile, con sein.", enNote:"Separable, with sein.", cat:"irregolare"},
  {inf:"mitnehmen", pres:"nimmt mit", pra:"nahm mit", perf:"hat mitgenommen", it:"portare con sé / prendere", en:"to take along", ex:[["Nimm einen Regenschirm mit!","Prendi un ombrello!"]], enex:[["Nimm einen Regenschirm mit!","Take an umbrella with you!"]], note:"Separabile. Anche: jdn mitnehmen = dare un passaggio a qualcuno.", enNote:"Separable. Also: jdn mitnehmen = to give someone a lift.", cat:"irregolare"},
  {inf:"mitsingen", pres:"singt mit", pra:"sang mit", perf:"hat mitgesungen", it:"cantare insieme", en:"to sing along", ex:[["Alle haben mitgesungen.","Hanno cantato tutti insieme."]], enex:[["Alle haben mitgesungen.","Everyone sang along."]], note:"Separabile. Il prefisso mit- si attacca a molti verbi: mitmachen, mitspielen, mitarbeiten.", enNote:"Separable. The mit- prefix works with many verbs: mitmachen, mitspielen, mitarbeiten.", cat:"irregolare"},
  {inf:"nachkommen", pres:"kommt nach", pra:"kam nach", perf:"ist nachgekommen", it:"raggiungere più tardi", en:"to follow later", ex:[["Geht schon vor, ich komme nach.","Andate avanti, vi raggiungo."]], enex:[["Geht schon vor, ich komme nach.","Go ahead, I'll follow you."]], note:"Separabile, con sein. Anche formale: einer Pflicht nachkommen = adempiere a un dovere.", enNote:"Separable, with sein. Also formal: einer Pflicht nachkommen = to fulfil a duty.", cat:"irregolare"},
  {inf:"nachsprechen", pres:"spricht nach", pra:"sprach nach", perf:"hat nachgesprochen", it:"ripetere (dopo qualcuno)", en:"to repeat after", ex:[["Sprechen Sie bitte nach!","Ripeta dopo di me, per favore!"]], enex:[["Sprechen Sie bitte nach!","Please repeat after me!"]], note:"Separabile. Tipico delle lezioni di lingua.", enNote:"Separable. Typical of language lessons.", cat:"irregolare"},
  {inf:"nachweisen", pres:"weist nach", pra:"wies nach", perf:"hat nachgewiesen", it:"dimostrare / documentare", en:"to prove / to provide evidence", ex:[["Sie muss ihre Deutschkenntnisse nachweisen.","Deve documentare la sua conoscenza del tedesco."]], enex:[["Sie muss ihre Deutschkenntnisse nachweisen.","She has to provide proof of her German."]], note:"Separabile, linguaggio burocratico. Il sostantivo è der Nachweis = l'attestato.", enNote:"Separable, bureaucratic register. The noun is der Nachweis = proof, certificate.", cat:"irregolare"},
  {inf:"nennen", pres:"nennt", pra:"nannte", perf:"hat genannt", it:"chiamare / nominare", en:"to name / to call", ex:[["Sie nennen ihren Sohn Max.","Chiamano il figlio Max."]], enex:[["Sie nennen ihren Sohn Max.","They're calling their son Max."]], note:"Verbo misto. Confronta heißen = chiamarsi (Ich heiße Max).", enNote:"Mixed verb. Compare heißen = to be called (Ich heiße Max).", cat:"irregolare"},
  {inf:"offen stehen", pres:"steht offen", pra:"stand offen", perf:"hat offen gestanden", it:"essere aperto / essere ancora possibile", en:"to be open", ex:[["Die Tür stand offen.","La porta era aperta."]], enex:[["Die Tür stand offen.","The door stood open."]], note:"Anche figurato: Dir stehen alle Türen offen. Nel sud: ist offen gestanden.", enNote:"Also figurative: Dir stehen alle Türen offen. In the south: ist offen gestanden.", cat:"irregolare"},
  {inf:"raten", pres:"rät", pra:"riet", perf:"hat geraten", it:"consigliare / indovinare", en:"to advise / to guess", ex:[["Ich rate dir, früher zu gehen.","Ti consiglio di andare prima."]], enex:[["Ich rate dir, früher zu gehen.","I advise you to leave earlier."]], note:"jdm raten: la persona in DATIVO. Anche: Rate mal! = indovina!", enNote:"jdm raten: the person takes the DATIVE. Also: Rate mal! = have a guess!", cat:"irregolare"},
  {inf:"rauskommen", pres:"kommt raus", pra:"kam raus", perf:"ist rausgekommen", it:"uscire / venire fuori", en:"to come out", ex:[["Wann kommt der neue Film raus?","Quando esce il film nuovo?"]], enex:[["Wann kommt der neue Film raus?","When does the new film come out?"]], note:"Separabile, con sein. Forma colloquiale di herauskommen.", enNote:"Separable, with sein. The colloquial form of herauskommen.", cat:"irregolare"},
  {inf:"reiten", pres:"reitet", pra:"ritt", perf:"ist geritten", it:"andare a cavallo", en:"to ride (a horse)", ex:[["Als Kind bin ich oft geritten.","Da bambino andavo spesso a cavallo."]], enex:[["Als Kind bin ich oft geritten.","As a child I often went riding."]], note:"Con sein come tutti i verbi di movimento. Con haben se c'è un oggetto: Er hat das Pferd geritten.", enNote:"With sein like all verbs of motion. With haben if there is an object: Er hat das Pferd geritten.", cat:"irregolare"},
  {inf:"riechen", pres:"riecht", pra:"roch", perf:"hat gerochen", it:"odorare / sentire l'odore", en:"to smell", ex:[["Hier riecht es nach Kaffee.","Qui c'è odore di caffè."]], enex:[["Hier riecht es nach Kaffee.","It smells of coffee here."]], note:"riechen nach + Dat = avere odore di · an etw Dat riechen = annusare qualcosa.", enNote:"riechen nach + Dat = to smell of · an etw Dat riechen = to sniff something.", cat:"irregolare"},
  {inf:"schießen", pres:"schießt", pra:"schoss", perf:"hat geschossen", it:"sparare / tirare", en:"to shoot", ex:[["Er hat ein Tor geschossen.","Ha segnato un gol."]], enex:[["Er hat ein Tor geschossen.","He scored a goal."]], note:"Anche nel calcio: ein Tor schießen. Con sein se indica un movimento rapido.", enNote:"Also in football: ein Tor schießen. With sein when it means a rapid movement.", cat:"irregolare"},
  {inf:"schlagen", pres:"schlägt", pra:"schlug", perf:"hat geschlagen", it:"battere / colpire", en:"to hit / to beat", ex:[["Die Uhr schlägt zwölf.","L'orologio batte le dodici."]], enex:[["Die Uhr schlägt zwölf.","The clock strikes twelve."]], note:"Base di vorschlagen (proporre) e einschlagen. Anche: Eier schlagen = sbattere le uova.", enNote:"The base of vorschlagen (to suggest) and einschlagen. Also: Eier schlagen = to beat eggs.", cat:"irregolare"},
  {inf:"schließen", pres:"schließt", pra:"schloss", perf:"hat geschlossen", it:"chiudere", en:"to close", ex:[["Das Museum schließt um 18 Uhr.","Il museo chiude alle 18."]], enex:[["Das Museum schließt um 18 Uhr.","The museum closes at 6 p.m."]], note:"Più formale di zumachen. Anche: Freundschaft schließen = stringere amicizia.", enNote:"More formal than zumachen. Also: Freundschaft schließen = to make friends.", cat:"irregolare"},
  {inf:"schneiden", pres:"schneidet", pra:"schnitt", perf:"hat geschnitten", it:"tagliare", en:"to cut", ex:[["Ich habe mir in den Finger geschnitten.","Mi sono tagliato un dito."]], enex:[["Ich habe mir in den Finger geschnitten.","I cut my finger."]], note:"Con la parte del corpo: sich Dat in etw Akk schneiden. Anche: sich die Haare schneiden lassen.", enNote:"With body parts: sich Dat in etw Akk schneiden. Also: sich die Haare schneiden lassen.", cat:"irregolare"},
  {inf:"schreien", pres:"schreit", pra:"schrie", perf:"hat geschrien", it:"gridare / urlare", en:"to shout / to scream", ex:[["Das Baby schreit die ganze Nacht.","Il bambino urla tutta la notte."]], enex:[["Das Baby schreit die ganze Nacht.","The baby cries all night."]], note:"Più forte di rufen (chiamare). Il sostantivo è der Schrei.", enNote:"Stronger than rufen (to call). The noun is der Schrei.", cat:"irregolare"},
  {inf:"schweigen", pres:"schweigt", pra:"schwieg", perf:"hat geschwiegen", it:"tacere", en:"to keep silent", ex:[["Er schwieg den ganzen Abend.","Ha taciuto tutta la sera."]], enex:[["Er schwieg den ganzen Abend.","He kept silent all evening."]], note:"Non è nicht sprechen: è un tacere attivo, scelto.", enNote:"Not the same as nicht sprechen: it is an active, chosen silence.", cat:"irregolare"},
  {inf:"schwimmen", pres:"schwimmt", pra:"schwamm", perf:"ist geschwommen", it:"nuotare", en:"to swim", ex:[["Wir sind im See geschwommen.","Abbiamo nuotato nel lago."]], enex:[["Wir sind im See geschwommen.","We swam in the lake."]], note:"Con sein quando c'è uno spostamento, con haben per l'attività sportiva in sé.", enNote:"With sein when there is movement, with haben for the sporting activity itself.", cat:"irregolare"},
  {inf:"spazieren gehen", pres:"geht spazieren", pra:"ging spazieren", perf:"ist spazieren gegangen", it:"andare a passeggio", en:"to go for a walk", ex:[["Am Sonntag gehen wir im Park spazieren.","La domenica andiamo a passeggiare nel parco."]], enex:[["Am Sonntag gehen wir im Park spazieren.","On Sundays we go for a walk in the park."]], note:"Si scrive staccato. Con sein, e il Partizip resta in due parole: spazieren gegangen.", enNote:"Written as two words. With sein, and the participle stays in two parts: spazieren gegangen.", cat:"irregolare"},
  {inf:"stattfinden", pres:"findet statt", pra:"fand statt", perf:"hat stattgefunden", it:"aver luogo / svolgersi", en:"to take place", ex:[["Das Konzert findet am Samstag statt.","Il concerto ha luogo sabato."]], enex:[["Das Konzert findet am Samstag statt.","The concert takes place on Saturday."]], note:"Separabile. Soggetto sempre una cosa, mai una persona.", enNote:"Separable. The subject is always a thing, never a person.", cat:"irregolare"},
  {inf:"stehen bleiben", pres:"bleibt stehen", pra:"blieb stehen", perf:"ist stehen geblieben", it:"fermarsi", en:"to stop / to come to a halt", ex:[["Meine Uhr ist stehen geblieben.","Il mio orologio si è fermato."]], enex:[["Meine Uhr ist stehen geblieben.","My watch has stopped."]], note:"Si scrive staccato, con sein. Per le persone: Bleib stehen! = fermati!", enNote:"Written as two words, with sein. For people: Bleib stehen! = stop!", cat:"irregolare"},
  {inf:"stehlen", pres:"stiehlt", pra:"stahl", perf:"hat gestohlen", it:"rubare", en:"to steal", ex:[["Man hat ihm das Fahrrad gestohlen.","Gli hanno rubato la bicicletta."]], enex:[["Man hat ihm das Fahrrad gestohlen.","Someone stole his bike."]], note:"jdm etw stehlen: la vittima va in dativo. Cambio di vocale e → ie → a → o.", enNote:"jdm etw stehlen: the victim takes the dative. Vowel change e → ie → a → o.", cat:"irregolare"},
  {inf:"sterben", pres:"stirbt", pra:"starb", perf:"ist gestorben", it:"morire", en:"to die", ex:[["Ihr Großvater ist letztes Jahr gestorben.","Suo nonno è morto l'anno scorso."]], enex:[["Ihr Großvater ist letztes Jahr gestorben.","Her grandfather died last year."]], note:"Con sein. sterben an + Dat = morire di (una malattia).", enNote:"With sein. sterben an + Dat = to die of (an illness).", cat:"irregolare"},
  {inf:"stinken", pres:"stinkt", pra:"stank", perf:"hat gestunken", it:"puzzare", en:"to stink", ex:[["Hier stinkt es nach Rauch.","Qui puzza di fumo."]], enex:[["Hier stinkt es nach Rauch.","It stinks of smoke in here."]], note:"stinken nach + Dat. Colloquiale anche: Das stinkt mir = questa cosa mi secca.", enNote:"stinken nach + Dat. Colloquially also: Das stinkt mir = that annoys me.", cat:"irregolare"},
  {inf:"übersehen", pres:"übersieht", pra:"übersah", perf:"hat übersehen", it:"non vedere / trascurare", en:"to overlook", ex:[["Ich habe den Fehler übersehen.","Non ho visto l'errore."]], enex:[["Ich habe den Fehler übersehen.","I overlooked the mistake."]], note:"Inseparabile: niente ge-, accento sulla radice. Attenzione: über- inseparabile qui, ma separabile in überlaufen.", enNote:"Inseparable: no ge-, stress on the stem. Note: über- is inseparable here, but separable in überlaufen.", cat:"irregolare"},
  {inf:"überweisen", pres:"überweist", pra:"überwies", perf:"hat überwiesen", it:"bonificare / inviare denaro", en:"to transfer (money)", ex:[["Ich überweise dir das Geld morgen.","Ti faccio il bonifico domani."]], enex:[["Ich überweise dir das Geld morgen.","I'll transfer you the money tomorrow."]], note:"Inseparabile. Il sostantivo è die Überweisung: sia il bonifico sia l'impegnativa dal medico.", enNote:"Inseparable. The noun is die Überweisung: both a bank transfer and a doctor's referral.", cat:"irregolare"},
  {inf:"übrig bleiben", pres:"bleibt übrig", pra:"blieb übrig", perf:"ist übrig geblieben", it:"avanzare / restare", en:"to be left over", ex:[["Vom Kuchen ist nichts übrig geblieben.","Della torta non è avanzato niente."]], enex:[["Vom Kuchen ist nichts übrig geblieben.","Nothing was left of the cake."]], note:"Si scrive staccato, con sein.", enNote:"Written as two words, with sein.", cat:"irregolare"},
  {inf:"sich umsehen", pres:"sieht sich um", pra:"sah sich um", perf:"hat sich umgesehen", it:"guardarsi intorno", en:"to look around", ex:[["Wir haben uns in der Stadt umgesehen.","Ci siamo guardati intorno in città."]], enex:[["Wir haben uns in der Stadt umgesehen.","We had a look around town."]], note:"Separabile e riflessivo. Anche: sich nach etw umsehen = cercare qualcosa in giro.", enNote:"Separable and reflexive. Also: sich nach etw umsehen = to look around for something.", cat:"irregolare"},
  {inf:"umsteigen", pres:"steigt um", pra:"stieg um", perf:"ist umgestiegen", it:"cambiare (mezzo)", en:"to change (trains)", ex:[["In München müssen wir umsteigen.","A Monaco dobbiamo cambiare treno."]], enex:[["In München müssen wir umsteigen.","We have to change trains in Munich."]], note:"Separabile, con sein. Anche figurato: auf etw Akk umsteigen = passare a qualcos'altro.", enNote:"Separable, with sein. Also figurative: auf etw Akk umsteigen = to switch to something else.", cat:"irregolare"},
  {inf:"umziehen", pres:"zieht um", pra:"zog um", perf:"ist umgezogen", it:"traslocare", en:"to move house", ex:[["Sie sind nach Hamburg umgezogen.","Si sono trasferiti ad Amburgo."]], enex:[["Sie sind nach Hamburg umgezogen.","They moved to Hamburg."]], note:"Separabile, con sein per il trasloco. Riflessivo con haben: sich umziehen = cambiarsi d'abito.", enNote:"Separable, with sein for moving house. Reflexive with haben: sich umziehen = to change clothes.", cat:"irregolare"},
  {inf:"unterbrechen", pres:"unterbricht", pra:"unterbrach", perf:"hat unterbrochen", it:"interrompere", en:"to interrupt", ex:[["Entschuldigung, darf ich kurz unterbrechen?","Scusate, posso interrompere un attimo?"]], enex:[["Entschuldigung, darf ich kurz unterbrechen?","Sorry, may I interrupt for a moment?"]], note:"Inseparabile: niente ge-.", enNote:"Inseparable: no ge-.", cat:"irregolare"},
  {inf:"untergehen", pres:"geht unter", pra:"ging unter", perf:"ist untergegangen", it:"tramontare / affondare", en:"to set / to sink", ex:[["Die Sonne geht um acht unter.","Il sole tramonta alle otto."]], enex:[["Die Sonne geht um acht unter.","The sun sets at eight."]], note:"Separabile, con sein. Qui unter- è separabile, a differenza di unterbrechen.", enNote:"Separable, with sein. Here unter- is separable, unlike in unterbrechen.", cat:"irregolare"},
  {inf:"unterhalten", pres:"unterhält", pra:"unterhielt", perf:"hat unterhalten", it:"intrattenere / mantenere", en:"to entertain / to support", ex:[["Der Komiker hat das Publikum gut unterhalten.","Il comico ha intrattenuto bene il pubblico."]], enex:[["Der Komiker hat das Publikum gut unterhalten.","The comedian entertained the audience well."]], note:"Inseparabile. Diverso dal riflessivo sich unterhalten mit + Dat = conversare con.", enNote:"Inseparable. Different from the reflexive sich unterhalten mit + Dat = to have a conversation with.", cat:"irregolare"},
  {inf:"unterschreiben", pres:"unterschreibt", pra:"unterschrieb", perf:"hat unterschrieben", it:"firmare", en:"to sign", ex:[["Bitte unterschreiben Sie hier.","Firmi qui, per favore."]], enex:[["Bitte unterschreiben Sie hier.","Please sign here."]], note:"Inseparabile: niente ge-. Il sostantivo è die Unterschrift.", enNote:"Inseparable: no ge-. The noun is die Unterschrift.", cat:"irregolare"},
  {inf:"unterstreichen", pres:"unterstreicht", pra:"unterstrich", perf:"hat unterstrichen", it:"sottolineare", en:"to underline", ex:[["Unterstreichen Sie die Verben im Text.","Sottolineate i verbi nel testo."]], enex:[["Unterstreichen Sie die Verben im Text.","Underline the verbs in the text."]], note:"Inseparabile. Anche figurato: dare risalto a un'affermazione.", enNote:"Inseparable. Also figurative: to emphasise a statement.", cat:"irregolare"},
  {inf:"verbieten", pres:"verbietet", pra:"verbot", perf:"hat verboten", it:"vietare", en:"to forbid", ex:[["Der Arzt hat mir das Rauchen verboten.","Il medico mi ha vietato di fumare."]], enex:[["Der Arzt hat mir das Rauchen verboten.","The doctor forbade me to smoke."]], note:"Inseparabile. jdm etw verbieten. Il contrario è erlauben. Vedi anche nicht dürfen.", enNote:"Inseparable. jdm etw verbieten. The opposite is erlauben. See also nicht dürfen.", cat:"irregolare"},
  {inf:"verbinden", pres:"verbindet", pra:"verband", perf:"hat verbunden", it:"collegare / mettere in comunicazione", en:"to connect", ex:[["Ich verbinde Sie mit Frau Meier.","Le passo la signora Meier."]], enex:[["Ich verbinde Sie mit Frau Meier.","I'll put you through to Ms Meier."]], note:"Inseparabile. Al telefono: Einen Moment, ich verbinde. Anche: fasciare una ferita.", enNote:"Inseparable. On the phone: Einen Moment, ich verbinde. Also: to bandage a wound.", cat:"irregolare"},
  {inf:"verbrennen", pres:"verbrennt", pra:"verbrannte", perf:"hat verbrannt", it:"bruciare / scottarsi", en:"to burn", ex:[["Ich habe mir die Hand verbrannt.","Mi sono bruciato la mano."]], enex:[["Ich habe mir die Hand verbrannt.","I burnt my hand."]], note:"Verbo misto e inseparabile. Con sein quando qualcosa brucia del tutto: Das Haus ist verbrannt.", enNote:"Mixed and inseparable. With sein when something burns down: Das Haus ist verbrannt.", cat:"irregolare"},
  {inf:"vergeben", pres:"vergibt", pra:"vergab", perf:"hat vergeben", it:"perdonare / assegnare", en:"to forgive / to award", ex:[["Der Platz ist schon vergeben.","Il posto è già assegnato."]], enex:[["Der Platz ist schon vergeben.","The place has already been taken."]], note:"Inseparabile. jdm etw vergeben = perdonare qualcosa a qualcuno. Vergeben sein = essere già impegnato.", enNote:"Inseparable. jdm etw vergeben = to forgive someone for something. Vergeben sein = to be taken.", cat:"irregolare"},
  {inf:"vergleichen", pres:"vergleicht", pra:"verglich", perf:"hat verglichen", it:"confrontare", en:"to compare", ex:[["Vergleichen Sie die beiden Texte.","Confronti i due testi."]], enex:[["Vergleichen Sie die beiden Texte.","Compare the two texts."]], note:"Inseparabile. etw mit etw Dat vergleichen. Il sostantivo è der Vergleich.", enNote:"Inseparable. etw mit etw Dat vergleichen. The noun is der Vergleich.", cat:"irregolare"},
  {inf:"verraten", pres:"verrät", pra:"verriet", perf:"hat verraten", it:"tradire / svelare", en:"to betray / to reveal", ex:[["Verrat mir dein Geheimnis!","Svelami il tuo segreto!"]], enex:[["Verrat mir dein Geheimnis!","Tell me your secret!"]], note:"Inseparabile. Nel parlato è spesso un semplice svelare, senza il peso del tradimento.", enNote:"Inseparable. Colloquially it often just means to let something slip, with no sense of betrayal.", cat:"irregolare"},
  {inf:"verschreiben", pres:"verschreibt", pra:"verschrieb", perf:"hat verschrieben", it:"prescrivere", en:"to prescribe", ex:[["Der Arzt hat mir ein Medikament verschrieben.","Il medico mi ha prescritto un farmaco."]], enex:[["Der Arzt hat mir ein Medikament verschrieben.","The doctor prescribed me a medicine."]], note:"Inseparabile. Riflessivo: sich verschreiben = fare un errore di scrittura.", enNote:"Inseparable. Reflexive: sich verschreiben = to make a slip of the pen.", cat:"irregolare"},
  {inf:"vertreten", pres:"vertritt", pra:"vertrat", perf:"hat vertreten", it:"sostituire / rappresentare", en:"to stand in for / to represent", ex:[["Ich vertrete meine Kollegin diese Woche.","Questa settimana sostituisco la mia collega."]], enex:[["Ich vertrete meine Kollegin diese Woche.","I'm standing in for my colleague this week."]], note:"Inseparabile. Anche: eine Meinung vertreten = sostenere un'opinione.", enNote:"Inseparable. Also: eine Meinung vertreten = to hold an opinion.", cat:"irregolare"},
  {inf:"vorkommen", pres:"kommt vor", pra:"kam vor", perf:"ist vorgekommen", it:"capitare / sembrare", en:"to happen / to seem", ex:[["So etwas kommt selten vor.","Una cosa del genere capita di rado."]], enex:[["So etwas kommt selten vor.","Something like that rarely happens."]], note:"Separabile, con sein. Anche: Das kommt mir bekannt vor = questo mi sembra familiare.", enNote:"Separable, with sein. Also: Das kommt mir bekannt vor = that seems familiar to me.", cat:"irregolare"},
  {inf:"vorlesen", pres:"liest vor", pra:"las vor", perf:"hat vorgelesen", it:"leggere ad alta voce", en:"to read aloud", ex:[["Sie liest den Kindern eine Geschichte vor.","Legge una storia ai bambini."]], enex:[["Sie liest den Kindern eine Geschichte vor.","She reads the children a story."]], note:"Separabile. jdm etw vorlesen: chi ascolta va in dativo.", enNote:"Separable. jdm etw vorlesen: the listener takes the dative.", cat:"irregolare"},
  {inf:"vorschlagen", pres:"schlägt vor", pra:"schlug vor", perf:"hat vorgeschlagen", it:"proporre", en:"to suggest", ex:[["Ich schlage vor, dass wir morgen anfangen.","Propongo di cominciare domani."]], enex:[["Ich schlage vor, dass wir morgen anfangen.","I suggest we start tomorrow."]], note:"Separabile. Il sostantivo è der Vorschlag.", enNote:"Separable. The noun is der Vorschlag.", cat:"irregolare"},
  {inf:"wach bleiben", pres:"bleibt wach", pra:"blieb wach", perf:"ist wach geblieben", it:"restare sveglio", en:"to stay awake", ex:[["Ich bin bis Mitternacht wach geblieben.","Sono rimasto sveglio fino a mezzanotte."]], enex:[["Ich bin bis Mitternacht wach geblieben.","I stayed awake until midnight."]], note:"Si scrive staccato, con sein.", enNote:"Written as two words, with sein.", cat:"irregolare"},
  {inf:"wahrnehmen", pres:"nimmt wahr", pra:"nahm wahr", perf:"hat wahrgenommen", it:"percepire / cogliere", en:"to perceive / to take up", ex:[["Ich habe den Geruch sofort wahrgenommen.","Ho percepito subito l'odore."]], enex:[["Ich habe den Geruch sofort wahrgenommen.","I noticed the smell immediately."]], note:"Separabile. Anche: einen Termin wahrnehmen = presentarsi a un appuntamento.", enNote:"Separable. Also: einen Termin wahrnehmen = to keep an appointment.", cat:"irregolare"},
  {inf:"wegfahren", pres:"fährt weg", pra:"fuhr weg", perf:"ist weggefahren", it:"partire / andare via", en:"to drive away", ex:[["Wir fahren am Wochenende weg.","Nel fine settimana partiamo."]], enex:[["Wir fahren am Wochenende weg.","We're going away at the weekend."]], note:"Separabile, con sein. weg- = via da qui.", enNote:"Separable, with sein. weg- = away from here.", cat:"irregolare"},
  {inf:"weggehen", pres:"geht weg", pra:"ging weg", perf:"ist weggegangen", it:"andarsene", en:"to go away", ex:[["Geh nicht weg, ich komme gleich.","Non andartene, arrivo subito."]], enex:[["Geh nicht weg, ich komme gleich.","Don't go away, I'm coming."]], note:"Separabile, con sein. Anche: uscire la sera (Wir gehen heute weg).", enNote:"Separable, with sein. Also: to go out for the evening (Wir gehen heute weg).", cat:"irregolare"},
  {inf:"weitergeben", pres:"gibt weiter", pra:"gab weiter", perf:"hat weitergegeben", it:"passare avanti / trasmettere", en:"to pass on", ex:[["Bitte gib die Information weiter.","Passa avanti l'informazione, per favore."]], enex:[["Bitte gib die Information weiter.","Please pass the information on."]], note:"Separabile. weiter- = continuare, andare oltre.", enNote:"Separable. weiter- = to carry on, to go further.", cat:"irregolare"},
  {inf:"weitergehen", pres:"geht weiter", pra:"ging weiter", perf:"ist weitergegangen", it:"proseguire / continuare", en:"to go on", ex:[["Wie geht es weiter?","Come si prosegue?"]], enex:[["Wie geht es weiter?","What happens next?"]], note:"Separabile, con sein. Sia camminare oltre, sia continuare una vicenda.", enNote:"Separable, with sein. Both walking on and a story continuing.", cat:"irregolare"},
  {inf:"widersprechen", pres:"widerspricht", pra:"widersprach", perf:"hat widersprochen", it:"contraddire", en:"to contradict", ex:[["Da muss ich Ihnen widersprechen.","Su questo devo contraddirla."]], enex:[["Da muss ich Ihnen widersprechen.","There I have to disagree with you."]], note:"Inseparabile. jdm widersprechen: la persona va in DATIVO. Il sostantivo è der Widerspruch.", enNote:"Inseparable. jdm widersprechen: the person takes the DATIVE. The noun is der Widerspruch.", cat:"irregolare"},
  {inf:"wiederkommen", pres:"kommt wieder", pra:"kam wieder", perf:"ist wiedergekommen", it:"tornare", en:"to come back", ex:[["Kommen Sie bitte morgen wieder.","Torni domani, per favore."]], enex:[["Kommen Sie bitte morgen wieder.","Please come back tomorrow."]], note:"Separabile, con sein. wieder- = di nuovo.", enNote:"Separable, with sein. wieder- = again.", cat:"irregolare"},
  {inf:"zunehmen", pres:"nimmt zu", pra:"nahm zu", perf:"hat zugenommen", it:"aumentare / ingrassare", en:"to increase / to put on weight", ex:[["Ich habe im Winter zugenommen.","D'inverno sono ingrassato."]], enex:[["Ich habe im Winter zugenommen.","I put on weight over the winter."]], note:"Separabile. Il contrario è abnehmen. Vale anche per quantità e fenomeni.", enNote:"Separable. The opposite is abnehmen. Also used for quantities and trends.", cat:"irregolare"},
  {inf:"zurückbekommen", pres:"bekommt zurück", pra:"bekam zurück", perf:"hat zurückbekommen", it:"riavere indietro", en:"to get back", ex:[["Ich habe mein Buch zurückbekommen.","Ho riavuto il mio libro."]], enex:[["Ich habe mein Buch zurückbekommen.","I got my book back."]], note:"Separabile, ma senza ge- perché bekommen è inseparabile.", enNote:"Separable, yet no ge- because bekommen is inseparable.", cat:"irregolare"},
  {inf:"zurückfahren", pres:"fährt zurück", pra:"fuhr zurück", perf:"ist zurückgefahren", it:"tornare (in auto, in treno)", en:"to drive back", ex:[["Wir fahren am Sonntag zurück.","Torniamo domenica."]], enex:[["Wir fahren am Sonntag zurück.","We're driving back on Sunday."]], note:"Separabile, con sein.", enNote:"Separable, with sein.", cat:"irregolare"},
  {inf:"zurückgehen", pres:"geht zurück", pra:"ging zurück", perf:"ist zurückgegangen", it:"tornare indietro / diminuire", en:"to go back / to decline", ex:[["Die Zahl der Unfälle ist zurückgegangen.","Il numero degli incidenti è diminuito."]], enex:[["Die Zahl der Unfälle ist zurückgegangen.","The number of accidents has gone down."]], note:"Separabile, con sein. Anche statistico: calare.", enNote:"Separable, with sein. Also statistical: to decrease.", cat:"irregolare"},
  {inf:"zurückliegen", pres:"liegt zurück", pra:"lag zurück", perf:"hat zurückgelegen", it:"risalire a / essere indietro", en:"to be in the past / to be behind", ex:[["Der Umzug liegt schon Jahre zurück.","Il trasloco risale a diversi anni fa."]], enex:[["Der Umzug liegt schon Jahre zurück.","The move was years ago."]], note:"Separabile. Nel sud: ist zurückgelegen.", enNote:"Separable. In the south: ist zurückgelegen.", cat:"irregolare"},
  {inf:"zurückrufen", pres:"ruft zurück", pra:"rief zurück", perf:"hat zurückgerufen", it:"richiamare (al telefono)", en:"to call back", ex:[["Ich rufe Sie später zurück.","La richiamo più tardi."]], enex:[["Ich rufe Sie später zurück.","I'll call you back later."]], note:"Separabile. Formula al telefono: Rufen Sie mich bitte zurück.", enNote:"Separable. Phone phrase: Rufen Sie mich bitte zurück.", cat:"irregolare"},
  {inf:"zusammenbleiben", pres:"bleibt zusammen", pra:"blieb zusammen", perf:"ist zusammengeblieben", it:"restare insieme", en:"to stay together", ex:[["Sie sind trotz allem zusammengeblieben.","Nonostante tutto sono rimasti insieme."]], enex:[["Sie sind trotz allem zusammengeblieben.","They stayed together despite everything."]], note:"Separabile, con sein.", enNote:"Separable, with sein.", cat:"irregolare"},
  {inf:"zusammenhalten", pres:"hält zusammen", pra:"hielt zusammen", perf:"hat zusammengehalten", it:"essere uniti / tenere insieme", en:"to stick together", ex:[["Die Familie hält immer zusammen.","La famiglia è sempre unita."]], enex:[["Die Familie hält immer zusammen.","The family always sticks together."]], note:"Separabile. Il sostantivo è der Zusammenhalt = la coesione.", enNote:"Separable. The noun is der Zusammenhalt = cohesion.", cat:"irregolare"},
  {inf:"zusammenhängen", pres:"hängt zusammen", pra:"hing zusammen", perf:"hat zusammengehangen", it:"essere collegato", en:"to be connected", ex:[["Die beiden Probleme hängen zusammen.","I due problemi sono collegati."]], enex:[["Die beiden Probleme hängen zusammen.","The two problems are connected."]], note:"Separabile. zusammenhängen mit + Dat. Il sostantivo è der Zusammenhang = il nesso. Nel sud: ist zusammengehangen.", enNote:"Separable. zusammenhängen mit + Dat. The noun is der Zusammenhang = connection. In the south: ist zusammengehangen.", cat:"irregolare"},
  {inf:"zu sein", pres:"ist zu", pra:"war zu", perf:"ist zu gewesen", it:"essere chiuso", en:"to be closed", ex:[["Der Laden ist heute zu.","Il negozio oggi è chiuso."]], enex:[["Der Laden ist heute zu.","The shop is closed today."]], note:"Colloquiale, il contrario di auf sein. Nel registro formale: geschlossen sein.", enNote:"Colloquial, the opposite of auf sein. In formal register: geschlossen sein.", cat:"irregolare"},
  {inf:"zutreffen", pres:"trifft zu", pra:"traf zu", perf:"hat zugetroffen", it:"essere esatto / valere", en:"to be true / to apply", ex:[["Das trifft auf mich nicht zu.","Questo non vale per me."]], enex:[["Das trifft auf mich nicht zu.","That doesn't apply to me."]], note:"Separabile. zutreffen auf + Akk. Tipico dei questionari: Zutreffendes bitte ankreuzen.", enNote:"Separable. zutreffen auf + Akk. Typical on forms: Zutreffendes bitte ankreuzen.", cat:"irregolare"},
  {inf:"betrügen", pres:"betrügt", pra:"betrog", perf:"hat betrogen", it:"tradire", en:"to cheat on / to deceive", ex:[["Er hat seine Frau betrogen.","Ha tradito sua moglie."]], enex:[["Er hat seine Frau betrogen.","He cheated on his wife."]], note:"Irregolare. jdn betrügen: anche nel senso di truffare qualcuno.", enNote:"Irregular. jdn betrügen: also means to swindle/con someone.", cat:"irregolare"},
  {inf:"beantragen", pres:"beantragt", pra:"beantragte", perf:"hat beantragt", it:"richiedere, fare domanda per", en:"to apply for", ex:[["Sie beantragt ein neues Visum.","Lei richiede un nuovo visto."]], enex:[["Sie beantragt ein neues Visum.","She is applying for a new visa."]], note:"etw Akk beantragen. Il sostantivo è der Antrag = la domanda.", enNote:"etw Akk beantragen. The noun is der Antrag = the application.", cat:"lavoro"},
  {inf:"ehren", pres:"ehrt", pra:"ehrte", perf:"hat geehrt", it:"onorare", en:"to honour", ex:[["Die Stadt ehrt die Feuerwehrleute.","La città onora i vigili del fuoco."]], enex:[["Die Stadt ehrt die Feuerwehrleute.","The city honours the firefighters."]], note:"Il sostantivo è die Ehre = l'onore.", enNote:"The noun is die Ehre = honour.", cat:"quotidiano"},
  {inf:"treiben", pres:"treibt", pra:"trieb", perf:"hat/ist getrieben", it:"spingere; galleggiare; essere trasportato", en:"to drive/push; to drift; to be carried", ex:[["Das Boot treibt auf dem See.","La barca galleggia sul lago."]], enex:[["Das Boot treibt auf dem See.","The boat drifts on the lake."]], note:"Irregolare, tre usi: jdn/etw treiben = spingere (hat); irgendwo treiben = galleggiare; irgendwohin treiben = essere trasportato (ist).", enNote:"Irregular, three uses: jdn/etw treiben = to push (hat); irgendwo treiben = to drift; irgendwohin treiben = to be carried (ist).", cat:"irregolare"},
  {inf:"entdecken", pres:"entdeckt", pra:"entdeckte", perf:"hat entdeckt", it:"scoprire", en:"to discover", ex:[["Kolumbus hat Amerika entdeckt.","Colombo ha scoperto l'America."]], enex:[["Kolumbus hat Amerika entdeckt.","Columbus discovered America."]], cat:"quotidiano"},
  {inf:"entführen", pres:"entführt", pra:"entführte", perf:"hat entführt", it:"rapire, sequestrare", en:"to kidnap", ex:[["Die Täter haben das Kind entführt.","I criminali hanno rapito il bambino."]], enex:[["Die Täter haben das Kind entführt.","The perpetrators kidnapped the child."]], cat:"quotidiano"},
  {inf:"belohnen", pres:"belohnt", pra:"belohnte", perf:"hat belohnt", it:"ricompensare, gratificare", en:"to reward", ex:[["Der Chef belohnt seine besten Mitarbeiter.","Il capo ricompensa i suoi migliori dipendenti."]], enex:[["Der Chef belohnt seine besten Mitarbeiter.","The boss rewards his best employees."]], note:"Il sostantivo è die Belohnung = la ricompensa.", enNote:"The noun is die Belohnung = the reward.", cat:"lavoro"},
  {inf:"ausüben", pres:"übt aus", pra:"übte aus", perf:"hat ausgeübt", it:"esercitare, praticare (un lavoro)", en:"to practise, to carry out", ex:[["Welchen Beruf üben Sie aus?","Che professione esercita?"]], enex:[["Welchen Beruf üben Sie aus?","What profession do you practise?"]], note:"Separabile. eine Tätigkeit/einen Beruf ausüben.", enNote:"Separable. eine Tätigkeit/einen Beruf ausüben.", cat:"lavoro"},
  {inf:"erhalten", pres:"erhält", pra:"erhielt", perf:"hat erhalten", it:"ricevere; conservare", en:"to receive; to preserve", ex:[["Ich habe deine E-Mail erhalten.","Ho ricevuto la tua email."]], enex:[["Ich habe deine E-Mail erhalten.","I received your email."]], note:"Irregolare, non separabile.", enNote:"Irregular, inseparable.", cat:"irregolare"},
  {inf:"umgehen", pres:"umgeht", pra:"umging", perf:"hat umgangen", it:"girare intorno a, evitare, schivare", en:"to bypass, to avoid", ex:[["Er versucht, das Problem zu umgehen.","Cerca di evitare il problema."]], enex:[["Er versucht, das Problem zu umgehen.","He tries to avoid the problem."]], note:"Non separabile in questo significato. Attenzione: umgehen separabile (ging um) = trattare/circolare.", enNote:"Inseparable in this meaning. Careful: separable umgehen (ging um) = to handle/circulate.", cat:"irregolare"},
  {inf:"sich leisten", pres:"leistet sich", pra:"leistete sich", perf:"hat sich geleistet", it:"permettersi qc.", en:"to afford", ex:[["Wir können uns diesen Urlaub leisten.","Possiamo permetterci questa vacanza."]], enex:[["Wir können uns diesen Urlaub leisten.","We can afford this holiday."]], note:"sich Dat etw Akk leisten. Senza il riflessivo: etw leisten = produrre/fornire una prestazione.", enNote:"sich Dat etw Akk leisten. Without the reflexive: etw leisten = to produce/provide, to achieve.", cat:"riflessivo"},
  {inf:"zurechtkommen", pres:"kommt zurecht", pra:"kam zurecht", perf:"ist zurechtgekommen", it:"cavarsela, farcela", en:"to manage, to cope", ex:[["Wir kommen auch ohne Geld zurecht.","Ce la facciamo anche senza soldi."]], enex:[["Wir kommen auch ohne Geld zurecht.","We manage even without money."]], note:"Separabile, con sein. mit jdm/etw zurechtkommen = andare d'accordo con / gestire qc.", enNote:"Separable, with sein. mit jdm/etw zurechtkommen = to get along with / to manage something.", cat:"irregolare"},
  {inf:"bestehen", pres:"besteht", pra:"bestand", perf:"hat bestanden", it:"consistere di; superare (un esame)", en:"to consist of; to pass (an exam)", ex:[["Die Prüfung besteht aus drei Teilen.","L'esame consiste di tre parti."],["Ich habe die Prüfung bestanden.","Ho superato l'esame."]], enex:[["Die Prüfung besteht aus drei Teilen.","The exam consists of three parts."],["Ich habe die Prüfung bestanden.","I passed the exam."]], note:"bestehen aus + Dat = consistere di; etw bestehen (senza aus) = superare qc.", enNote:"bestehen aus + Dat = to consist of; etw bestehen (without aus) = to pass something.", cat:"irregolare"},
  {inf:"sich ausdenken", pres:"denkt sich aus", pra:"dachte sich aus", perf:"hat sich ausgedacht", it:"escogitare, inventare", en:"to think up, to invent", ex:[["Sie hat sich eine gute Ausrede ausgedacht.","Ha escogitato una buona scusa."]], enex:[["Sie hat sich eine gute Ausrede ausgedacht.","She thought up a good excuse."]], cat:"riflessivo"},
  {inf:"sich auskennen", pres:"kennt sich aus", pra:"kannte sich aus", perf:"hat sich ausgekannt", it:"conoscere bene, essere esperto (di)", en:"to know one's way around, to be well-versed", ex:[["Er kennt sich mit Computern gut aus.","Lui se ne intende bene di computer."]], enex:[["Er kennt sich mit Computern gut aus.","He knows a lot about computers."]], note:"sich auskennen mit + Dat.", enNote:"sich auskennen mit + Dat.", cat:"riflessivo"},
  {inf:"überzeugen", pres:"überzeugt", pra:"überzeugte", perf:"hat überzeugt", it:"convincere", en:"to convince", ex:[["Sie hat mich mit ihren Argumenten überzeugt.","Mi ha convinto con i suoi argomenti."]], enex:[["Sie hat mich mit ihren Argumenten überzeugt.","She convinced me with her arguments."]], cat:"comunicazione"},
  {inf:"umgeben", pres:"umgibt", pra:"umgab", perf:"hat umgeben", it:"circondare", en:"to surround", ex:[["Ein hoher Zaun umgibt das Grundstück.","Un'alta recinzione circonda il terreno."]], enex:[["Ein hoher Zaun umgibt das Grundstück.","A high fence surrounds the property."]], cat:"irregolare"},
  {inf:"plaudern", pres:"plaudert", pra:"plauderte", perf:"hat geplaudert", it:"chiacchierare", en:"to chat", ex:[["Wir haben lange über alte Zeiten geplaudert.","Abbiamo chiacchierato a lungo dei vecchi tempi."]], enex:[["Wir haben lange über alte Zeiten geplaudert.","We chatted for a long time about old times."]], cat:"comunicazione"},
  {inf:"überwiegen", pres:"überwiegt", pra:"überwog", perf:"hat überwogen", it:"prevalere", en:"to prevail, to outweigh", ex:[["Die Vorteile überwiegen die Nachteile.","I vantaggi prevalgono sugli svantaggi."]], enex:[["Die Vorteile überwiegen die Nachteile.","The advantages outweigh the disadvantages."]], note:"Aggettivo derivato: überwiegend = prevalente.", enNote:"Derived adjective: überwiegend = prevailing/predominant.", cat:"irregolare"},
  {inf:"lassen", pres:"lässt", pra:"ließ", perf:"hat gelassen", it:"lasciare; far fare", en:"to leave; to let; to have something done", ex:[["Ich habe mir ein neues Piercing machen lassen.","Mi sono fatto fare un nuovo piercing."]], enex:[["Ich habe mir ein neues Piercing machen lassen.","I've had a new piercing done."]], note:"Quattro significati: lasciare (Ich lasse das Handy zu Hause), permettere (Lass mich schlafen!), far fare (Ich lasse das Auto reparieren), lasciare in un posto. Nel Perfekt con un secondo verbo: habe machen lassen, mai «gelassen». Vedi le schede «Das Verb lassen» e «Perfekt mit doppeltem Infinitiv».", enNote:"Four meanings: to leave (Ich lasse das Handy zu Hause), to let (Lass mich schlafen!), to have something done (Ich lasse das Auto reparieren), to leave somewhere. In the Perfekt with a second verb: habe machen lassen, never «gelassen». See «Das Verb lassen» and «Perfekt mit doppeltem Infinitiv».", cat:"irregolare"},
  {inf:"auswandern", pres:"wandert aus", pra:"wanderte aus", perf:"ist ausgewandert", it:"emigrare", en:"to emigrate", ex:[["Stell dir vor, Herr Breit will nach Kanada auswandern.","Immagina, il signor Breit vuole emigrare in Canada."]], enex:[["Stell dir vor, Herr Breit will nach Kanada auswandern.","Imagine, Mr Breit wants to emigrate to Canada."]], note:"Separabile, con sein. aus = fuori: si lascia il proprio paese. Contrario: einwandern.", enNote:"Separable, with sein. aus = out: you leave your country. Opposite: einwandern.", cat:"movimento"},
  {inf:"einwandern", pres:"wandert ein", pra:"wanderte ein", perf:"ist eingewandert", it:"immigrare", en:"to immigrate", ex:[["Warum sind Sie eigentlich in die Schweiz eingewandert?","Ma perché è immigrato in Svizzera?"]], enex:[["Warum sind Sie eigentlich in die Schweiz eingewandert?","Why did you immigrate to Switzerland, by the way?"]], note:"Separabile, con sein. in + Akk. (Wohin?): in die Schweiz einwandern.", enNote:"Separable, with sein. in + Akk. (where to?): in die Schweiz einwandern.", cat:"movimento"},
  {inf:"klappen", pres:"klappt", pra:"klappte", perf:"hat geklappt", it:"funzionare, andare in porto (colloquiale)", en:"to work out", ex:[["Ich wollte nach Hamburg gehen. Aber das hat nicht geklappt.","Volevo andare ad Amburgo, ma non è andata."]], enex:[["Ich wollte nach Hamburg gehen. Aber das hat nicht geklappt.","I wanted to go to Hamburg. But it didn't work out."]], note:"Colloquiale. Il soggetto è la cosa, non la persona: Das hat (nicht) geklappt.", enNote:"Colloquial. The subject is the thing, not the person: Das hat (nicht) geklappt.", cat:"quotidiano"},
  {inf:"verlängern", pres:"verlängert", pra:"verlängerte", perf:"hat verlängert", it:"prolungare, rinnovare", en:"to extend, to renew", ex:[["Ich habe mein Visum verlängern lassen.","Ho fatto rinnovare il mio visto."]], enex:[["Ich habe mein Visum verlängern lassen.","I've had my visa extended."]], note:"Inseparabile (ver-): Partizip senza ge-. Da lang: rendere più lungo.", enNote:"Inseparable (ver-): Partizip without ge-. From lang: to make longer.", cat:"quotidiano"},
  {inf:"weiterleiten", pres:"leitet weiter", pra:"leitete weiter", perf:"hat weitergeleitet", it:"inoltrare", en:"to forward", ex:[["Der Projektmanager hat der Kollegin die E-Mail weitergeleitet.","Il project manager ha inoltrato l'e-mail alla collega."]], enex:[["Der Projektmanager hat der Kollegin die E-Mail weitergeleitet.","The project manager forwarded the email to his colleague."]], note:"Separabile. jdm etw Akk weiterleiten: la persona in dativo.", enNote:"Separable. jdm etw Akk weiterleiten: the person takes the dative.", cat:"comunicazione"},
  {inf:"schnarchen", pres:"schnarcht", pra:"schnarchte", perf:"hat geschnarcht", it:"russare", en:"to snore", ex:[["Ich habe meinen Nachbarn die ganze Nacht schnarchen hören.","Ho sentito il mio vicino russare tutta la notte."]], enex:[["Ich habe meinen Nachbarn die ganze Nacht schnarchen hören.","I heard my neighbour snoring all night."]], note:"Regolare.", enNote:"Regular.", cat:"quotidiano"},
  {inf:"sich integrieren", pres:"integriert sich", pra:"integrierte sich", perf:"hat sich integriert", it:"integrarsi", en:"to integrate", ex:[["Es ist nicht leicht, sich in einem neuen Land zu integrieren.","Non è facile integrarsi in un nuovo paese."]], enex:[["Es ist nicht leicht, sich in einem neuen Land zu integrieren.","It isn't easy to integrate into a new country."]], note:"in + Akk.: sich in die Gesellschaft integrieren. Verbi in -ieren: Partizip senza ge-.", enNote:"in + Akk.: sich in die Gesellschaft integrieren. Verbs in -ieren: Partizip without ge-.", cat:"riflessivo"},
  {inf:"erwarten", pres:"erwartet", pra:"erwartete", perf:"hat erwartet", it:"aspettarsi", en:"to expect", ex:[["Der Kurs war besser, als ich erwartet hatte.","Il corso è stato migliore di quanto mi aspettassi."]], enex:[["Der Kurs war besser, als ich erwartet hatte.","The course was better than I had expected."]], note:"≠ warten auf + Akk. (aspettare qualcuno). erwarten = prevedere, contare su: Ich erwarte viel von dir.", enNote:"≠ warten auf + Akk. (to wait for). erwarten = to expect: Ich erwarte viel von dir.", cat:"mentale"},
  {inf:"hoffen", pres:"hofft", pra:"hoffte", perf:"hat gehofft", it:"sperare", en:"to hope", ex:[["Das Essen schmeckt nicht so gut, wie ich gehofft hatte.","Il cibo non è buono come speravo."]], enex:[["Das Essen schmeckt nicht so gut, wie ich gehofft hatte.","The food isn't as good as I had hoped."]], note:"hoffen auf + Akk.: Ich hoffe auf besseres Wetter. Spesso con dass: Ich hoffe, dass du kommst.", enNote:"hoffen auf + Akk.: Ich hoffe auf besseres Wetter. Often with dass: Ich hoffe, dass du kommst.", cat:"mentale"},
  {inf:"überwinden", pres:"überwindet", pra:"überwand", perf:"hat überwunden", it:"superare (un ostacolo, una paura)", en:"to overcome", ex:[["Wie kann man Vorurteile überwinden?","Come si possono superare i pregiudizi?"]], enex:[["Wie kann man Vorurteile überwinden?","How can you overcome prejudices?"]], note:"Inseparabile: accento su -win-, Partizip senza ge-.", enNote:"Inseparable: stress on -win-, Partizip without ge-.", cat:"irregolare"},
  {inf:"erweitern", pres:"erweitert", pra:"erweiterte", perf:"hat erweitert", it:"ampliare, allargare", en:"to broaden, to expand", ex:[["Im Ausland kann man seinen Horizont erweitern.","All'estero si possono allargare i propri orizzonti."]], enex:[["Im Ausland kann man seinen Horizont erweitern.","Abroad you can broaden your horizons."]], note:"Inseparabile (er-). Da weit: rendere più largo.", enNote:"Inseparable (er-). From weit: to make wider.", cat:"quotidiano"},
  {inf:"kritisieren", pres:"kritisiert", pra:"kritisierte", perf:"hat kritisiert", it:"criticare", en:"to criticise", ex:[["Er kritisiert immer alles.","Critica sempre tutto."]], enex:[["Er kritisiert immer alles.","He always criticises everything."]], note:"= Kritik üben an + Dat. Verbi in -ieren: Partizip senza ge-.", enNote:"= Kritik üben an + Dat. Verbs in -ieren: Partizip without ge-.", cat:"comunicazione"},
  {inf:"lösen", pres:"löst", pra:"löste", perf:"hat gelöst", it:"risolvere", en:"to solve", ex:[["Im Assessment-Center müssen die Bewerber Probleme lösen.","All'assessment center i candidati devono risolvere problemi."]], enex:[["Im Assessment-Center müssen die Bewerber Probleme lösen.","At the assessment centre the applicants have to solve problems."]], note:"ein Problem / eine Aufgabe / einen Konflikt lösen.", enNote:"ein Problem / eine Aufgabe / einen Konflikt lösen.", cat:"lavoro"},
  {inf:"schenken", pres:"schenkt", pra:"schenkte", perf:"hat geschenkt", it:"regalare", en:"to give (as a present)", ex:[["Mein Sohn schenkt seinem Freund sein Fahrrad. → Er schenkt es ihm.","Mio figlio regala la sua bici al suo amico. → Gliela regala."]], enex:[["Mein Sohn schenkt seinem Freund sein Fahrrad. → Er schenkt es ihm.","My son gives his friend his bike. → He gives it to him."]], note:"jdm etw schenken: persona in dativo, cosa in accusativo. das Geschenk = il regalo.", enNote:"jdm etw schenken: person in the dative, thing in the accusative. das Geschenk = the present.", cat:"quotidiano"},
  {inf:"erklären", pres:"erklärt", pra:"erklärte", perf:"hat erklärt", it:"spiegare", en:"to explain", ex:[["Erklär mir bitte nochmal die Grammatik. – Ich habe sie dir doch schon erklärt.","Spiegami di nuovo la grammatica, per favore. – Ma te l'ho già spiegata."]], enex:[["Erklär mir bitte nochmal die Grammatik. – Ich habe sie dir doch schon erklärt.","Please explain the grammar to me again. – But I've already explained it to you."]], note:"Inseparabile (er-): Partizip senza ge-. jdm etw erklären. die Erklärung = la spiegazione.", enNote:"Inseparable (er-): Partizip without ge-. jdm etw erklären. die Erklärung = the explanation.", cat:"comunicazione"},
  {inf:"schicken", pres:"schickt", pra:"schickte", perf:"hat geschickt", it:"mandare, spedire", en:"to send", ex:[["Ich schicke meinem Bruder den Brief. → Ich schicke ihn ihm.","Mando la lettera a mio fratello. → Gliela mando."]], enex:[["Ich schicke meinem Bruder den Brief. → Ich schicke ihn ihm.","I'm sending my brother the letter. → I'm sending it to him."]], note:"jdm etw schicken. Sinonimo più formale: senden.", enNote:"jdm etw schicken. More formal synonym: senden.", cat:"comunicazione"},
  {inf:"winken", pres:"winkt", pra:"winkte", perf:"hat gewinkt", it:"salutare con la mano, fare cenno", en:"to wave", ex:[["Ich habe sie vom Fenster winken sehen.","L'ho vista salutare dalla finestra."]], enex:[["Ich habe sie vom Fenster winken sehen.","I saw her waving from the window."]], note:"jdm winken. Nel parlato anche il participio gewunken.", enNote:"jdm winken. Colloquially also the participle gewunken.", cat:"quotidiano"},
  {inf:"wünschen", pres:"wünscht", pra:"wünschte", perf:"hat gewünscht", it:"augurare; desiderare", en:"to wish", ex:[["Die Tante wünscht ihrer Nichte alles Gute.","La zia augura ogni bene a sua nipote."]], enex:[["Die Tante wünscht ihrer Nichte alles Gute.","The aunt wishes her niece all the best."]], note:"jdm etw wünschen = augurare · sich Dat etw wünschen = desiderare: Ich wünsche mir ein Fahrrad.", enNote:"jdm etw wünschen = to wish someone something · sich Dat etw wünschen = to want: Ich wünsche mir ein Fahrrad.", cat:"comunicazione"},
  {inf:"verdienen", pres:"verdient", pra:"verdiente", perf:"hat verdient", it:"guadagnare; meritare", en:"to earn; to deserve", ex:[["Sie verdient doppelt so viel wie ihr Mann.","Guadagna il doppio di suo marito."]], enex:[["Sie verdient doppelt so viel wie ihr Mann.","She earns twice as much as her husband."]], note:"Inseparabile (ver-). Due significati: Geld verdienen = guadagnare · eine Pause verdienen = meritare una pausa.", enNote:"Inseparable (ver-). Two meanings: Geld verdienen = to earn money · eine Pause verdienen = to deserve a break.", cat:"lavoro"},
  {inf:"vervollständigen", pres:"vervollständigt", pra:"vervollständigte", perf:"hat vervollständigt", it:"completare", en:"to complete", ex:[["Wie würdest du die Sätze vervollständigen?","Come completeresti le frasi?"]], enex:[["Wie würdest du die Sätze vervollständigen?","How would you complete the sentences?"]], note:"Da vollständig (completo). Tipico delle consegne degli esercizi, come ergänzen.", enNote:"From vollständig (complete). Typical in exercise instructions, like ergänzen.", cat:"comunicazione"},
  {inf:"informieren", pres:"informiert", pra:"informierte", perf:"hat informiert", it:"informare", en:"to inform", ex:[["Ich habe meine Lehrerin darüber informiert, dass ich krank bin.","Ho informato la mia insegnante che sono malato."]], enex:[["Ich habe meine Lehrerin darüber informiert, dass ich krank bin.","I informed my teacher that I am ill."]], note:"jdn (Akk) über etw (Akk) informieren. Con una frase intera: darüber informieren, dass … Verbo in -ieren: niente ge- nel Partizip (informiert). Riflessivo: sich über etw informieren = informarsi su qualcosa.", enNote:"jdn (Akk) über etw (Akk) informieren. With a whole clause: darüber informieren, dass … Verb in -ieren: no ge- in the Partizip (informiert). Reflexive: sich über etw informieren = to find out about something.", cat:"verbi con preposizione"}
];
